head.script:
//
/*BLGCHI001-C101 (B8 stage 3): the embedded jQuery 2.2.4 core is removed;
   every remaining script below is vanilla (C29/C32/C30 ports and the
   feed belt). The excision keeps the C29/C32 module tail that was
   appended after the library in this block.*/
  // Sticky navigation
/*BLGCHI001-C32: the header and its navigation are CSS-sticky (base header
rule above, top:0), so they stay visible on home, post and static pages. The
C29 sticky-nav port was defined but never called (and recomputed the header
offset each scroll), so the whole header scrolled out of view; it is removed.*/
// Show categories
/*BLGCHI001-C29 (B8 stage 1): vanilla port of the jQuery #box slideToggle and
the shared widget-fade helpers below. jQuery's animate stack (200/400/600ms
speeds, slideUp/slideDown/slideToggle, fadeIn) is replaced by a small CSS
transition helper - same 300/400ms timings so the feel is unchanged.*/
function hmReady(fn){if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",fn);}else{fn();}}
function hmSlideOpen(el){el.style.overflow="hidden";el.style.transition="height .4s ease, opacity .4s ease";el.style.height="0px";el.style.opacity="0";el.style.display="block";var h=el.scrollHeight+"px";requestAnimationFrame(function(){el.style.height=h;el.style.opacity="1"});setTimeout(function(){el.style.height="";el.style.opacity="";el.style.transition="";el.style.overflow=""},420)}
function hmSlideClose(el){el.style.overflow="hidden";el.style.transition="height .4s ease, opacity .4s ease";el.style.height=el.scrollHeight+"px";el.style.opacity="";requestAnimationFrame(function(){el.style.height="0px";el.style.opacity="0"});setTimeout(function(){el.style.display="none";el.style.height="";el.style.transition="";el.style.overflow=""},420)}
function hmSlideVisible(el){return !!(el.offsetWidth||el.offsetHeight)}
function hmSlideToggle(el){if(hmSlideVisible(el)){hmSlideClose(el)}else{hmSlideOpen(el)}}
function hmFadeIn(el){el.style.opacity="0";el.style.transition="opacity .3s ease";requestAnimationFrame(function(){el.style.opacity="1"});setTimeout(function(){el.style.opacity="";el.style.transition=""},320)}
/*BLGCHI001-C29 (B8 stage 1): the feed template functions used to parse each
entry's content through a detached jQuery wrapper to find the first image;
DOMParser does the same job without jQuery or a detached element hanging off
the live document. */
function hmFirstImgSrc(html){try{var doc=new DOMParser().parseFromString(html,"text/html");var im=doc.querySelector("img");return im?(im.getAttribute("src")||undefined):undefined}catch(e){return undefined}}
hmReady(function(){var box=document.getElementById("box");var btn=document.getElementById("tombol_show");if(!box||!btn)return;box.style.display="none";btn.addEventListener("click",function(){hmSlideToggle(box)})});
/*BLGCHI001-C211: the drawer Pages block collapses the same way as Categories --
the header toggles it and it starts closed, so the 14 page links stay out of
the way until the reader opens it.*/
hmReady(function(){var box=document.getElementById("drawer-pages-box");var btn=document.getElementById("drawer-pages-toggle");if(!box||!btn)return;box.style.display="none";btn.addEventListener("click",function(){hmSlideToggle(box)})});
// CSS menu
/*BLGCHI001-C29 (B8 stage 1): vanilla port of the jQuery cssmenu accordion
and the .menu/.close-menu overlay toggles. jQuery's :odd/:even addClass had
no CSS consumer (removed as dead decoration); the inline left/off-canvas
styles and the slide timings are unchanged. */
hmReady(function(){var menu=document.getElementById("cssmenu");if(menu){var links=menu.querySelectorAll(":scope > ul > li > a");for(var i=0;i<links.length;i++){(function(a){a.addEventListener("click",function(ev){var li=a.closest("li");var chk=a.nextElementSibling;var sub=chk&&chk.tagName==="UL";if(!sub)return;ev.preventDefault();menu.querySelectorAll("li.active").forEach(function(x){x.classList.remove("active")});li.classList.add("active");if(hmSlideVisible(chk)){li.classList.remove("active");hmSlideClose(chk)}else{for(var j=0;j<links.length;j++){var s2=links[j].nextElementSibling;if(s2&&s2.tagName==="UL"&&s2!==chk&&hmSlideVisible(s2))hmSlideClose(s2)}hmSlideOpen(chk)}})})(links[i]);}}
var cm=document.getElementById("css-menu");if(!cm)return;document.querySelectorAll(".menu").forEach(function(m){m.addEventListener("click",function(){cm.style.left="0"})});document.querySelectorAll(".close-menu").forEach(function(c){c.addEventListener("click",function(){cm.style.left="-100%"})});});
// Lazy AdSense
var lazyadsense=!1;window.addEventListener("scroll",function(){(0!=document.documentElement.scrollTop&&!1===lazyadsense||0!=document.body.scrollTop&&!1===lazyadsense)&&(!function(){var e=document.createElement("script");e.type="text/javascript",e.async=!0,e.src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js";var a=document.getElementsByTagName("script")[0];a.parentNode.insertBefore(e,a)}(),lazyadsense=!0)},!0);
// Multi-tab widget
/*BLGCHI001-C29 (B8 stage 1): vanilla port of the jQuery multitab switcher -
same classes, same href targets, fadeIn becomes the shared hmFadeIn helper.*/
hmReady(function(){var tabsUl=document.querySelector("ul.multitab-widget-content-tabs-id");if(!tabsUl)return;var tabs=tabsUl.querySelectorAll("li a");if(!tabs.length)return;var panels=document.querySelectorAll(".multitab-widget-content-widget-id");for(var i=0;i<panels.length;i++)panels[i].style.display="none";tabs[0].classList.add("multitab-widget-current");var first=tabs[0].getAttribute("href");if(first&&first.length>1){var p0=document.querySelector(first);if(p0)p0.style.display=""}for(var i=0;i<tabs.length;i++){(function(tab){tab.addEventListener("click",function(ev){ev.preventDefault();for(var j=0;j<tabs.length;j++)tabs[j].classList.remove("multitab-widget-current","a");tab.classList.add("multitab-widget-current");for(var j=0;j<panels.length;j++)panels[j].style.display="none";var href=tab.getAttribute("href");if(href&&href.length>1){var el=document.querySelector(href);if(el){el.style.display="";hmFadeIn(el)}}})})(tabs[i])}});
// Mobile URL cleanup
var uri=window.location.toString();if(uri.indexOf("%3D","%3D")>0){var clean_uri=uri.substring(0,uri.indexOf("%3D"));window.history.replaceState({},document.title,clean_uri)}
var uri=window.location.toString();if(uri.indexOf("%3D%3D","%3D%3D")>0){var clean_uri=uri.substring(0,uri.indexOf("%3D%3D"));window.history.replaceState({},document.title,clean_uri)}
var uri=window.location.toString();if(uri.indexOf("&m=1","&m=1")>0){var clean_uri=uri.substring(0,uri.indexOf("&m=1"));window.history.replaceState({},document.title,clean_uri)}
var uri=window.location.toString();if(uri.indexOf("?m=1","?m=1")>0){var clean_uri=uri.substring(0,uri.indexOf("?m=1"));window.history.replaceState({},document.title,clean_uri)}
// Sticky widgets
/*BLGCHI001-C30 (B8 stage 2): vanilla port of the theia sticky-sidebar plugin
for the one element that used it: #sticky-sidebar (same option set - additionalMarginTop
54, additionalMarginBottom 0, container = the sidebar's parent column). The
plugin's wrapper div, padding probes and resize re-binding are not needed;
the same visible behavior - fixed under the top offset, clamped at the
container bottom (absolute positioning against the flow box), restored to
static above it - is reproduced here. position:sticky would silently do
nothing here: the sidebar is floated and its parent clips overflow. */
/*BLGCHI001-C160 (B42): operator redirected the approach pre-commit: the sticky target is the sidebar's LAST widget -- the bottom house-ad section #sidebar-ads2 -- not the Trending Now panel. With the last widget pinned, nothing later in the DOM can paint over it, so the z-order sketch for the Trending panel (a z-index set/clear) was abandoned and no z-index ships; the Trending panel scrolls normally again. The header pin, height spacer, #content-wrapper travel container, dock math, post-page-only engagement and mobile clear are unchanged. */ /*BLGCHI001-C159 (B41): the C30 port has been dead since it shipped: it pins #sticky-sidebar inside its parentElement, but the theme collapses that parent (#main-sidebar is a plain block around a floated child, so its offsetHeight is 0 -- measured live: parent 0, sidebar 1050 -- so the s.offsetHeight>=p.offsetHeight guard always trips and the rail just scrolls away, leaving the post-page column empty). Upgrade per operator: pin the Trending panel (#popular-sidebar2, the "Trending Now" widget) instead, under the sticky header, with the travel container #content-wrapper (the column that spans the post body), dock math top=min(hh+8,cb-y-h) so it rides up as the content end and the footer arrive (bottom never passes the container), a height spacer keeps the ad sections below it from jumping while it is out of flow, guard against the collapsed parent is replaced by nat.height>=c.offsetHeight, and it engages only on post pages (date-URL match) so the homepage rails stay as they are; mobile (<769px) clears as in C30.*/function hmStickySidebar(){var s=document.getElementById("sticky-sidebar");if(!s)return;if(!/\/[0-9]{4}\/[0-9]{2}\/[^/]+\.html$/.test(location.pathname))return;var c=document.getElementById("content-wrapper")||s.parentElement;if(!c)return;var t=document.getElementById("sidebar-ads2")||s;var nat=null,sp=null;function measure(){var r=t.getBoundingClientRect();nat={top:r.top+window.pageYOffset,left:r.left,width:t.offsetWidth,height:t.offsetHeight}}function spacer(on){if(!on){if(sp&&sp.parentNode){sp.parentNode.removeChild(sp)}sp=null}else if(!sp&&nat&&nat.height>0){sp=document.createElement("div");sp.style.height=nat.height+"px";sp.style.width=nat.width+"px";t.parentNode.insertBefore(sp,t)}}function clear(){if(t.style.position){spacer(false);t.style.position="";t.style.top="";t.style.left="";t.style.width=""}measure()}function upd(){if(window.innerWidth<769){if(t.style.position)clear();return}var hd=document.querySelector("header"),hh=hd?hd.offsetHeight:54;if(t.style.position!=="fixed")measure();if(nat.height>=c.offsetHeight){if(t.style.position)clear();return}var y=window.pageYOffset,cb=c.getBoundingClientRect().bottom+window.pageYOffset;if(y+hh<nat.top){if(t.style.position)clear();return}var top=Math.min(hh+8,cb-y-nat.height);spacer(true);t.style.position="fixed";t.style.top=top+"px";t.style.left=nat.left+"px";t.style.width=nat.width+"px"}measure();upd();window.addEventListener("scroll",upd,{passive:true});window.addEventListener("resize",function(){clear();upd()},{passive:true})} hmReady(function(){hmStickySidebar()})
/* BLGCHI001-C335: Blogger-native contact form on the Contact page. The
   ContactForm widget renders inside the hidden footer holder section; when a
   page body carries #hm-contact-slot the widget node is moved into the page
   card. Moving preserves the form end to end: Blogger's widgets.js binds the
   submit handler to the element before DOMContentLoaded (the registration
   block sits at the foot of the served HTML), and listeners travel with the
   node. The slot's existence IS the page check -- no URL parsing, so the
   mirror pages (any paste of the contact body) get the form the same way.
   Without the slot the widget stays hidden on every other page; if the
   widget instance is missing (holder removed in a derived build), the slot
   states it instead of leaving a hole. */
hmReady(function(){var slot=document.getElementById("hm-contact-slot");if(!slot)return;var w=document.getElementById("ContactForm1");if(w){w.classList.add("hm-contact-widget");slot.appendChild(w)}else{var f=document.createElement("p");f.className="hm-contact-fallback";f.textContent="The message form is unavailable right now. Check back soon, or use the comment area of any post.";slot.appendChild(f)}})
//

//
/*BLGCHI001-C30 (B8 stage 2): vanilla port of jquery.lazyload. The plugin's
contract is kept: each image's real src is parked in data-hm-original, the
below-fold images get the placeholder immediately (the
bandwidth saving was the whole point), and on appear the real source is
swapped back and faded in with a CSS opacity transition (effect fadeIn,
threshold 0 as before). The appear signal comes from IntersectionObserver
(C15 discipline) instead of the plugin's scroll math and fold helpers. Stage-2 alignment with the other machine's C30: the pre-load placeholder is the same branded palette SVG the rendered slots carry, not the old invisible 1x1 GIF. */
var HM_PLACEHOLDER='data:image/svg+xml,%3Csvg%0Axmlns=%22http:%2F%2Fwww.w3.org%2F2000%2Fsvg%22%0AviewBox=%220%0A0%0A320%0A180%22%0ApreserveAspectRatio=%22xMidYMid%0Aslice%22%3E%3Cdefs%3E%3ClinearGradient%0Aid=%22a%22%0Ax1=%220%22%0Ay1=%220%22%0Ax2=%221%22%0Ay2=%221%22%3E%3Cstop%0Aoffset=%220%22%0Astop-color=%22%233357a7%22%2F%3E%3Cstop%0Aoffset=%221%22%0Astop-color=%22%231976d2%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Crect%0Awidth=%22320%22%0Aheight=%22180%22%0Afill=%22url%28%23a%29%22%2F%3E%3Cg%0Afill=%22none%22%0Astroke=%22%23fff%22%0Astroke-opacity=%22.5%22%0Astroke-width=%227%22%0Astroke-linecap=%22round%22%0Astroke-linejoin=%22round%22%3E%3Crect%0Ax=%22102%22%0Ay=%2252%22%0Awidth=%22116%22%0Aheight=%2276%22%0Arx=%229%22%2F%3E%3Ccircle%0Acx=%22134%22%0Acy=%2281%22%0Ar=%227%22%2F%3E%3Cpath%0Ad=%22M106%0A117l24-26%0A18%0A18%0A22-28%0A44%0A34%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E';
function hmLazyImages(){
  var imgs=document.querySelectorAll('.overlay-fotopopuler img,.overlay-video img,.overlay-foto img,.overlay-card img,.post-thumbnail img,.post-body img,.related-post img,.overlay-card1 img,.overlay-card2 img,#populer .item-thumbnail img,.next-article img,#PopularPosts7 ul li .item-thumbnail img,#topik-card4 img');
  if(!imgs.length)return;
  if(!("IntersectionObserver" in window))return;
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(!e.isIntersecting)return;
      var img=e.target;io.unobserve(img);
      img.style.opacity="0";img.style.transition="opacity .3s ease";
      img.addEventListener("load",function(){img.style.opacity="1";setTimeout(function(){img.style.opacity="";img.style.transition=""},320)},{once:true});
      var real=img.getAttribute("data-hm-original");
      /* C151 (B32): a swap that never lands must never leave a hole. If the real source fails (or the load event is missed), put the branded placeholder back and clear the fade so the slot stays visible. Attached before the swap so no failure window slips by. */
      if(real){
        img.addEventListener("error",function(){img.style.opacity="";img.style.transition="";img.setAttribute("src",HM_PLACEHOLDER)},{once:true});
        img.setAttribute("src",real);
      }
    });
  });
  for(var k=0;k<imgs.length;k++){
    var im=imgs[k];
    if(!im.getAttribute("data-hm-original")){
      im.setAttribute("data-hm-original",im.getAttribute("src")||"");
      im.setAttribute("src",HM_PLACEHOLDER);
    }
    io.observe(im);
  }
}
hmReady(hmLazyImages);
//

