head.b:skin:
:root{--hm-bg:#edf1f8;--hm-surface:#ffffff;--hm-text:#111111;--hm-muted:#666666;--hm-border:#e5e9f0;--hm-accent:#3357a7;--hm-link:#1976d2;--hm-font:'Segoe UI',Roboto,'Noto Sans','Noto Sans Devanagari','Noto Sans Bengali','Noto Sans Tamil','Noto Sans Telugu','Noto Sans Kannada','Noto Sans Malayalam','Noto Sans Gujarati','Noto Sans Gurmukhi','Noto Sans Oriya','Nirmala UI',Helvetica,Arial,sans-serif}
.hm-skip{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:100000}.hm-skip:focus{position:fixed;left:16px;top:16px;width:auto;height:auto;padding:12px 20px;background:var(--hm-text);color:var(--hm-bg);font:600 14px/1.3 var(--hm-font);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.2);outline:3px solid var(--hm-accent);outline-offset:2px;z-index:100000}
html.dark{--hm-bg:#1f2a36;--hm-surface:#293542;--hm-text:#eef3f9;--hm-muted:#b3c0cf;--hm-border:#3c4b5d;--hm-accent:#8fb4ff;--hm-link:#7ec8ff}
html,body,div,span,applet,object,iframe,h1,h2,h3,h4,h5,h6,p,blockquote,pre,a,abbr,acronym,address,big,cite,code,del,dfn,em,img,ins,kbd,q,s,samp,small,strike,strong,sub,sup,tt,var,b,u,i,center,dl,dt,dd,ol,ul,li,fieldset,form,label,legend,table,caption,tbody,tfoot,thead,tr,th,td,article,aside,canvas,details,embed,figure,figcaption,footer,header,hgroup,menu,nav,output,ruby,section,summary,time,mark,audio,video{margin:0;padding:0;border:0;/*font-size:100%;*/font:inherit;vertical-align:baseline;}img{vertical-align:middle;width:auto;height:auto;max-width:100%}img:hover,a.slider-image:hover{transition:all .2s ease;filter:contrast(120%)}.separator a{border:none !important;margin:0 !important}
/* HTML5 display-role reset for older browsers */
article,aside,details,figcaption,figure,footer,header,hgroup,menu,nav,section{display:block;}body{background:var(--hm-bg);color:var(--hm-text);font-family:var(--hm-font);font-size:16px;line-height:1.3;text-rendering: optimizeSpeed;transition: all 0.31s ease 0s;display:block;}*{margin:0;padding:0;text-decoration: none;}html{display:block;}blockquote,q{quotes:none;}blockquote::before,blockquote::after,q::before,q::after{content:&#39;&#39;;content:none;}table{border-collapse:collapse;border-spacing:0;} a{color:var(--hm-link);vertical-align:baseline;outline:0; transition:all .2s ease;}
/* Blogger CSS Reset */
html{scroll-behavior:smooth;}.section,.widget{margin:0;padding:0;}i{font-style:italic;}b{font-weight:700;}u{border-bottom:1px solid;}*,*:before,*:after{-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box}@keyframes Gradient{0%{background-position:0 50%}50%{background-position:100% 50%}100%{background-position:0 50%}}
.navbar,.blog-feeds,.feed-links,#backlinks-container,.blog-mobile-link{display:none;}
