.lighter,.lighter *{transition:all 0.31s ease 0s}.lighter{position:fixed;top:0;bottom:0;left:0;right:0;z-index:400000;opacity:1}.lighter.fade{opacity:0}.lighter.fade .lighter-container{transform:scale(.5)}.lighter img{width:100%;height:100%}.lighter .lighter-overlay{background:rgba(0,0,0,.75);height:100%;width:100%}.lighter .lighter-container{background:white;position:absolute;z-index:400000;top:50%;left:50%;right:50%;bottom:50%;box-shadow:0 2px 8px rgba(0,0,0,.5)}.lighter .lighter-container .lighter-close{top:0;right:0;width:44px;height:44px;margin:-22px;line-height:44px;font-size:16pt;font-family:Helvetica,Arial,serif}.lighter .lighter-container .lighter-next{display:none;right:40px;top:50%;width:44px;height:44px;margin:-22px 0;line-height:44px;font-size:32pt;font-family:Times,serif}.lighter .lighter-container .lighter-prev{display:none;left:40px;top:50%;width:44px;height:44px;margin:-22px;line-height:24pt;font-size:34px;font-family:Times,serif}.lighter .lighter-container .lighter-next,.lighter .lighter-container .lighter-prev,.lighter .lighter-container .lighter-close{cursor:pointer;position:absolute;z-index:800000;text-align:center;border-radius:40px;color:rgba(255,255,255,.8);background:rgba(255,0,0,.6)}.lighter .lighter-container .lighter-next:hover,.lighter .lighter-container .lighter-prev:hover,.lighter .lighter-container .lighter-close:hover{color:white;text-decoration:none;background:rgba(255,0,0,.9)}.lighter .lighter-container .lighter-next:active,.lighter .lighter-container .lighter-prev:active,.lighter .lighter-container .lighter-close:active{color:white;background:rgba(0,0,0,.6)}.SEO{font-size:1px;color:transparent;position:absolute}.quickedit,.edit-post,.item-control,.post-footer,.icon-action,.read-more-snippet{display:none}textarea:focus,input:focus{outline:none}*:focus{outline:none}.post-body .separator a,.post-body .separator span{margin-left:0!important}.separator{clear:none!important}.separator img{width:100%;height:auto;border-radius:4px}.separator a::after{display:none!important}.separator a{display:inherit!important}.post-body iframe{border-radius:4px}.tr-caption-container{margin:0!important;width:100%;position:relative}.tr-caption{width:100%;font-family:var(--hm-font);font-size:14px;text-align:left!important;line-height:1.4;padding:10px 0;color:var(--hm-muted)}blockquote{font-style:italic;padding:12px 0 0 24px;border-left:1px solid #e9ebee;margin:0;border-top:1px solid #e9ebee}blockquote:before{content:"\f10d";margin:0 5px 0 0;font-family:FontAwesome;color:#d00}blockquote:after{content:"\f10e";margin:0 0 0 5px;font-family:FontAwesome;color:#d00}.post-body ul,.post-body ol{padding:0 40px}.tr-caption-container img{border-radius:4px;height:auto;width:100%}iframe{width:100%}.tr-caption-container a{display:block!important;padding:0 !important;width:100%}.tr-caption-container a::after{display:none!important}h2 a{color:#000}
/*CSS*/
header{background:#fff;width:100%;position:-webkit-sticky;position:sticky;top:0;z-index:9}#featured-slider .post-descript{z-index:2}header a{text-decoration:none}#in-header{overflow:hidden;width:auto;max-width:1140px;margin:0 auto;height:74px;padding:0 20px;box-sizing:border-box}#logo-header{width:auto;max-width:500px;margin:auto}#Header1_headerimg{width:auto;max-height:44px;margin:15px auto;height:auto}.tglhariini{width:auto;position:fixed;top:17px;left:80px;height:40px}.hari{display:block;font-weight:700;margin:3px 0 -2px 0}.tanggal{display:block;font-size:12px;font-family:var(--hm-font)}#right-header{overflow:hidden;text-align:center;margin:auto;border-radius:12px;box-shadow:0 0 10px 0 rgba(0,0,0,.1);position:absolute;right:20px;top:23px;display:flex;align-items:center}#right-header a{color:#3357a7;display:block;padding:0 8px;line-height:28px;font-size:14px;font-weight:700;background:#55c189 linear-gradient(-50deg,#ea3a7e,#20aadb,#23e0b3) repeat scroll 0 0;background-clip:border-box;-webkit-background-clip:text;-webkit-text-fill-color:transparent}#right-header a::before{margin:0 5px 0 0;content:"\f201";font-family:FontAwesome;color:#3357a7;font-weight:400}#right-header h2{display:none}#right-header a{display:inline-flex;align-items:center}
#HTML90{display:none}#HTML95{display:none}.hm-search-toggle{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 6px 0 0;padding:0;background:transparent;border:0;border-radius:50%;color:inherit;cursor:pointer;text-decoration:none}.hm-search-toggle:focus-visible{outline:2px solid var(--hm-link);outline-offset:2px}.hm-search-toggle svg{width:20px;height:20px}#hm-search-panel{position:fixed;top:74px;left:0;right:0;z-index:20;background:var(--hm-surface);border-bottom:1px solid var(--hm-border);box-shadow:0 12px 30px -12px rgba(0,0,0,.25)}#hm-search-panel[hidden]{display:none}.hm-search-inner{max-width:720px;margin:0 auto;padding:14px 16px 16px}.hm-search-row{display:flex;gap:8px}#hm-search-input{flex:1;min-width:0;min-height:44px;box-sizing:border-box;padding:10px 12px;font-size:15px;border:1px solid var(--hm-border);border-radius:8px;background:var(--hm-bg);color:var(--hm-text)}.hm-search-close{min-height:44px;min-width:44px;padding:0 14px;border:1px solid var(--hm-border);border-radius:8px;background:transparent;color:inherit;cursor:pointer}.hm-search-results{margin:8px 0 0;padding:0;list-style:none;max-height:50vh;overflow:auto}.hm-search-results li a{display:flex;gap:10px;align-items:center;padding:8px 4px;text-decoration:none;color:inherit;border-top:1px solid var(--hm-border)}.hm-search-thumb{width:52px;height:52px;flex:none;border-radius:8px;background:var(--hm-border);object-fit:cover}.hm-search-results .hm-t{font-weight:700;font-size:14px}.hm-search-results .hm-m{font-size:12px;color:var(--hm-muted)}.hm-search-results li a.hm-active,.hm-search-results li a:hover{background:var(--hm-bg)}.hm-search-foot{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:8px 4px 0;font-size:13px;color:var(--hm-muted)}.hm-search-foot a{font-weight:700}.hm-dark-toggle{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 6px 0 0;padding:0;background:transparent;border:0;bor