body.rm-on {overflow: hidden; background: var(--hm-bg)}
body.rm-on .post-outer {position: fixed; top: env(safe-area-inset-top, 0px); bottom: calc(12px + env(safe-area-inset-bottom, 0px)); left: 0; right: 0; margin: 0 auto; width: calc(100% - 24px); width: min(72ch, calc(100% - 24px)); padding: 0 4px; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; z-index: 9998; background: var(--hm-surface); box-shadow: none}
body.rm-on .post-outer {scrollbar-width: none; -ms-overflow-style: none}
body.rm-on .post-outer::-webkit-scrollbar {display: none}
body.rm-on .post-outer {padding-bottom: calc(56px + env(safe-area-inset-bottom, 0px))}
body.rm-on .post-outer .post-title.entry-title {font-family: Georgia, 'Times New Roman', serif; font-weight: 700; font-size: clamp(26px, 3.4vw, 38px); line-height: 1.3; text-transform: none; text-decoration: none; text-align: left}
body.rm-on .post-body {font-family: Georgia, 'Times New Roman', serif; font-size: 1.125em; line-height: 1.8; --rm-fs: 1}
body.rm-on .post-body img {max-width: 100%; height: auto}
body.rm-fs-1 .post-body {--rm-fs: 1.111}
body.rm-fs-2 .post-body {--rm-fs: 1.222}
body.rm-on .post-body :where(p, h1, h2, h3, h4, li, blockquote) {font-size: calc(1em * var(--rm-fs, 1))}
.rm-exit {display: none}
body.rm-on .rm-exit {display: block; max-width: 68ch; margin: 24px auto 8px; padding: 14px 16px; border: 1px solid var(--hm-border); border-radius: 12px; background: var(--hm-surface); text-align: center}
.rm-exit button {display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 10px 18px; border: 1px solid var(--hm-border); border-radius: 999px; background: var(--hm-text); color: var(--hm-bg); font: 600 14px/1.3 var(--hm-font); cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
.rm-exit button:focus-visible {outline: 3px solid var(--hm-accent); outline-offset: 2px}
.rm-say {background: none; color: inherit; box-shadow: inset 0 -2px 0 currentColor; -webkit-box-decoration-break: clone; box-decoration-break: clone}
.rm-word {background: color-mix(in srgb, var(--hm-accent) 35%, black); color: rgba(255, 255, 255, 0.96); border-radius: 4px; padding: 0 .12em; margin: 0 -.12em; -webkit-box-decoration-break: clone; box-decoration-break: clone}
.rm-entry-box {display: flex; align-items: center; gap: 12px; flex-wrap: wrap; background: transparent; border: 0; padding: 0; margin: 16px 0 16px}/*BLGCHI001-C193 (B85): symmetric rhythm above/below the row*/ /*BLGCHI001-C190 (B83): left-row entry below breadcrumbs (operator pick C)*/
.rm-entry {display: inline-flex; align-items: center; justify-content: center; gap: 8px; width: auto; min-height: 44px; padding: 10px 22px; border: 1px solid var(--hm-accent); border-radius: 999px; background: var(--hm-accent); color: var(--hm-surface); font: 600 14px/1 var(--hm-font); cursor: pointer; white-space: nowrap}
.rm-entry:hover {border-color: var(--hm-text)}
.rm-entry[aria-pressed='true'] {background: var(--hm-text); color: var(--hm-bg)}
.rm-entry:focus-visible {outline: 3px solid var(--hm-accent); outline-offset: 2px}
.rm-entry-top {display: none}
.rm-entry-top[hidden] {display: none !important}
@media (max-width: 960px) {
  .rm-entry-top {display: inline-flex; width: auto; min-height: 44px; margin: 14px 0; padding: 8px 14px; font-size: 13px}
  .rm-entry-box {display: none}
  body.rm-on .rm-entry-top {display: none}
}
.rm-bar {position: sticky; top: 0; z-index: 9999; display: none; flex: 0 0 auto; align-items: center; gap: 2px; width: max-content; max-width: 100%; margin: 0 auto 10px; padding: 5px; border: 1px solid var(--hm-border); border-radius: 999px; background: var(--hm-surface); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12); overflow-x: auto; scrollbar-width: none}
.rm-bar::-webkit-scrollbar {display: none}
body.rm-on .rm-bar {display: flex}
.rm-bar button {display: inline-flex; align-items: center; justify-content: center; min-width: 44px; height: 44px; padding: 0 10px; border: 0; border-radius: 999px; background: transparent; color: var(--hm-text); font: 600 13px/1 var(--hm-font); cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
.rm-bar button:hover {background: rgba(128, 128, 128, 0.14)}
.rm-bar button[aria-pressed='true'] {background: var(--hm-text); color: var(--hm-bg)}
.rm-bar button:disabled {opacity: .45; cursor: default}
.rm-bar .rm-pos {min-width: 40px; padding: 0 4px; text-align: center; font: 400 11px/1 var(--hm-font); color: var(--hm-muted)}
.rm-bar button:focus-visible {outline: 3px solid var(--hm-accent); outline-offset: 2px}
.rm-pager {display: none}
body.rm-on .rm-pager {display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 4px; width: 100%; max-width: 68ch; margin: 0 auto 18px; padding: 4px 0; border-top: 1px solid var(--hm-border); border-bottom: 1px solid var(--hm-border)}
.rm-pager a {display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 6px; border-radius: 10px; color: var(--hm-text); font: 600 13px/1.3 var(--hm-font); text-decoration: none; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
.rm-pager a:hover {background: rgba(128, 128, 128, 0.14)}
.rm-pager a:focus-visible {outline: 3px solid var(--hm-accent); outline-offset: 2px}
.rm-pager .rm-pager-older {justify-self: end}
.rm-pager .rm-pager-home {justify-self: center; min-width: 44px; padding: 0; justify-content: center}
.rm-pager svg {flex: 0 0 auto}
.rm-resume-chip {position: fixed; bottom: calc(16px + env(safe-area-inset-bottom, 0px)); left: 50%; transform: translateX(-50%); width: max-content; max-width: calc(100vw - 24px); z-index: 9999; display: none; align-items: center; gap: 8px; padding: 8px 8px 8px 14px; border: 1px solid var(--hm-border); border-radius: 999px; background: var(--hm-surface); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12); font: 400 13px/1 var(--hm-font); color: var(--hm-text)}
.rm-resume-chip.rm-show {display: inline-flex}
.rm-resume-chip button {flex: 0 0 auto; white-space: nowrap; min-height: 44px; padding: 7px 12px; border: 0; border-radius: 999px; background: linear-gradient(135deg, color-mix(in srgb, var(--hm-accent) 45%, black) 0%, color-mix(in srgb, var(--hm-accent) 70%, black) 100%); color: rgba(255, 255, 255, 0.96); font: 600 12px/1 var(--hm-font); cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
@media (max-width: 480px) {
  .rm-bar {justify-content: center; gap: 0; padding: 4px}
  .rm-bar .rm-pos {display: none}
  .rm-resume-chip {bottom: calc(16px + env(safe-area-inset-bottom, 0px))}
  body.rm-on .post-outer {width: calc(100% - 8px); bottom: calc(12px + env(safe-area-inset-bottom, 0px))}
  body.rm-on .post-body {font-size: 1.2em; overflow-wrap: break-word}
  .rm-exit button {width: 100%}
}
@media print {.rm-bar, .rm-pager, .rm-resume-chip, .rm-entry-box, .rm-exit {display: none !important}}
/* BLGCHI001-C56 (B20): print flattens the paper surface -- light page, dark
   article ink, chrome/ad/drawer/reader-furniture hidden; no html.dark scope,
   so both modes print the same sheet (operator standard WCAG 2.2 AA + 44px). */
@media print {
  body {background: #fff !important; color: #111 !important}
  #css-menu, header, #footer-section, footer, #main-sidebar, #sticky-sidebar,
  #top-ads, #top-menu, .top-bagikan, .bottom-share, #author-share, .bagikan,
  .komentar, #commentfb, #fbcomment-title, .lighter, .rm-bar, .rm-pager,
  .rm-resume-chip, .rm-entry-box, .rm-exit, .hm-dark-toggle, #blog-pager,
  .next-article {display: none !important}
  #content-wrapper, #main, .post-outer {background: #fff !important; width: 100% !important; max-width: 100% !important; margin: 0 !important; padding: 0 !important; box-shadow: none !important}
  .post-body, .post-body p, .post-body li, .post-body h2, .post-body h3, .post-body h4, .post-title.entry-title {color: #111 !important; background: transparent !important}
  a {color: #111 !important; text-decoration: underline !important}
}
/* BLGCHI001-C56 (B20): forced-colors pins interactive chrome to system
   colors only -- the OS owns the palette, so no hex/rgb/var() may appear. */
@media (forced-colors: active) {
  a {color: LinkText}
  a:visited {color: VisitedText}
  button {background: ButtonFace; color: ButtonText; border: 1px solid ButtonBorder; forced-color-adjust: none}
  input, textarea, select {background: Field; color: FieldText; border: 1px solid ButtonBorder}
  ::selection {background: Highlight; color: HighlightText}
  .hm-dark-toggle, #css-menu a, #post-labels-bawah a, .title-next-article span {forced-color-adjust: none}
  #css-menu a {color: LinkText}
  #post-labels-bawah a {color: LinkText; border: 1px solid ButtonBorder}
  .title-next-article span {background: Canvas; color: CanvasText; border-left: 8px solid LinkText}
}
/* C110 article design system (demo posts + buyer docs): llian-grade article
   furniture, theme-native -- every color is a --hm-* token or an
   already-shipped literal, so dark mode and recolors follow free. */
.hm-art-hero{background:linear-gradient(120deg,#3357a7 0%,#1976d2 100%);color:#fff;border-radius:12px;padding:30px 28px;margin:6px 0 22px}
.hm-art-kicker{display:inline-block;font-family:var(--hm-font);font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;background:rgba(255,255,255,.18);color:#fff;padding:5px 12px;border-radius:999px;margin-bottom:12px}
.hm-art-lede{margin:0;color:rgba(255,255,255,.92);font-size:19px;line-height:1.6}
.hm-art-card{background:var(--hm-surface);border:1px solid var(--hm-border);border-radius:10px;padding:24px 28px;margin-bottom:18px}
.hm-art-card h2{margin:0 0 12px;padding-bottom:8px;border-bottom:2px solid var(--hm-accent)}
.hm-art-card p{margin:0 0 12px}
.hm-art-card p:last-child{margin-bottom:0}
.hm-art-card ul,.hm-art-card ol{margin:0 0 12px;padding-left:22px}
.hm-art-card li{margin-bottom:7px}
.hm-art-card code{background:var(--hm-bg);color:var(--hm-link);padding:2px 7px;border-radius:5px;font-size:.9em}
.hm-art-tip{background:var(--hm-bg);border:1px solid var(--hm-border);border-left:5px solid var(--hm-link);border-radius:0 8px 8px 0;padding:14px 18px;margin-bottom:18px}
.hm-art-tags{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 18px}
.hm-art-tags a{background:var(--hm-bg);color:var(--hm-link);font-size:13px;font-weight:600;padding:4px 12px;border-radius:999px;text-decoration:none}
.hm-art-tags a::after{display:none}
.hm-art-next{background:var(--hm-bg);border:1px solid var(--hm-border);border-radius:10px;padding:20px 24px;margin-bottom:6px}
.hm-art-next-title{margin:0 0 8px;font-family:var(--hm-font);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--hm-muted)}
html.dark .hm-art-hero{background:linear-gradient(120deg,#1b2530 0%,#3357a7 100%)}
/* C120 post-page reference parity: bottom Trending Now collapse. Reference
   selectors kept; colors are skin tokens (the reference #fff/#3357a7 pair
   glares in dark mode). Box starts collapsed per the reference. C126: the
   operator picked full 44px toggle buttons over the reference 30x24 after
   a visual comparison -- owl-dot idiom (flex-centered icon, focus ring).
   C128: h2 reserves a 100px right zone (min-height 44px) and the rule
   stops before the buttons -- the 44px pair overlapped the full-width
   rule live. C343: bracket instead -- the visible toggle rides the rule
   line inside one bordered box (---[ + ]--- / ---[ - ]---, one button at
   a time per C121), the 1px line running full-width behind it; the
   margin-right stop never shrank the line (abs-pos left:0 + width:100% +
   right:auto ignores margin-right), so the solid bracket background is
   what interrupts it. C346: heading keeps overflow visible so the badge
   is never clipped (44px buttons fill the 44px heading, the badge must
   float above it), and the glyph drops to 14px so the 44px touch box
   reads as heading furniture, not a billboard -- the 44px floor itself
   is untouched (C126 + rule 6). C347: operator says the 44px pair still
   dwarfs the 20px heading -- the bracket drops to 28px to match the
   title/rule scale, glyph stays 14px. Documented compact exception: 28px
   still clears the WCAG 2.2 AA 24px target floor (the repo 44px is the
   stricter house rule, kept everywhere else); rule 6 pins 28px here. */
/*BLGCHI001-C162 (B44): drops the stale min-height:44px from the 44px-button era -- the 24px toggle centers on the h2 box (top:50% + margin-top) while the rule line sits at text level, so the button floated 6px below the line (measured live: button cy == h2 cy in both pairs, badge moves nothing); the h2 now shrink-wraps like #fbcomment-title and the button lands on the line. The count badge stays position:absolute (out of flow) so it can never count toward button alignment, per operator requirement; the same fixed-slot mechanism guards both toggle pairs (see validator). */
#PopularPosts7 h2{position:relative;padding-right:100px;overflow:visible}
#tampilkan,#sembunyikan{position:absolute;top:50%;right:0;margin-top:-12px;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center;padding:0;background:#fff;border:1px solid #3357a7;border-radius:3px;color:var(--hm-accent);font-size:14px;cursor:pointer;z-index:1;-webkit-appearance:none;appearance:none}
#tampilkan:hover,#sembunyikan:hover{color:var(--hm-link);transition:all .2s ease}
#tampilkan:focus-visible,#sembunyikan:focus-visible{outline:2px solid var(--hm-link);outline-offset:2px}
/*BLGCHI001-C162 (B44, 2/2): the inherited -12px pull-up left the rule line 2.5px below the toggle/box middle (measured live, desktop + mobile: the title link wraps text+line in an extra inline box); -15px lands the line within 0.5px of center on both. Scoped to PopularPosts7 only -- other headings keep the base pull-up. */
#PopularPosts7 .h2border-popular{margin-right:100px;margin-top:-15px}
#box-trending{display:none}
html.dark #tampilkan,html.dark #sembunyikan{background:var(--hm-surface)}
html.dark #sembunyikan{border-left-color:var(--hm-border)}
/* C344: the collapsed (+) toggle carries a pulsing count badge -- the number
   of posts inside the box, so the reader sees something is there and clicks.
   Count is filled by the C342 script (no Blogger size accessor for data:posts);
   badge hides when the box is empty; motion stops under reduced-motion.
   C348: border:0 -- the badge is a span inside the heading, so the base
   `#PopularPosts7 h2 span` 8px blue left bar leaked onto it (full red only). */
#tampilkan #trending-count{position:absolute;top:-6px;right:-6px;min-width:14px;height:14px;box-sizing:border-box;padding:0 2px;border:0;border-radius:999px;background:#e60e35;color:#fff;font-size:9px;font-weight:700;line-height:14px;text-align:center;box-shadow:0 0 0 0 rgba(230,14,53,.5);animation:hmTrendPing 2s ease-out infinite}
@keyframes hmTrendPing{0%{box-shadow:0 0 0 0 rgba(230,14,53,.5)}70%{box-shadow:0 0 0 9px rgba(230,14,53,0)}100%{box-shadow:0 0 0 0 rgba(230,14,53,0)}}
@media (prefers-reduced-motion:reduce){#tampilkan #trending-count{animation:none}}
/* C350: single-slot toggles (24px, closed bracket, end of line) + comments
   collapse + disclaimer alignment. Both Trending buttons now share ONE slot
   at the line end (the old side-by-side slots left the visible half with an
   open edge); paint() just swaps which half shows, so the bracket is always
   closed. The Comments heading gets the same feature (ctampilkan/csembunyikan
   collapse the disclaimer + native comments box, open by default). The
   disclaimer text aligns with the heading text (+16px) with a 12px gap so it
   no longer crowds Trending. Compact floor is now 24px for both pairs (WCAG
   2.2 AA minimum; rule 6 pins it). */
#fbcomment-title{position:relative;padding-right:32px;overflow:visible}/*BLGCHI001-C189 (B82): visible like Trending so the corner badge is never clipped*/
#ctampilkan,#csembunyikan{position:absolute;top:50%;right:0;margin-top:-12px;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center;padding:0;background:#fff;border:1px solid #3357a7;border-radius:3px;color:var(--hm-accent);font-size:12px;cursor:pointer;z-index:1;-webkit-appearance:none;appearance:none}
#ctampilkan:hover,#csembunyikan:hover{color:var(--hm-link);transition:all .2s ease}
#ctampilkan:focus-visible,#csembunyikan:focus-visible{outline:2px solid var(--hm-link);outline-offset:2px}
html.dark #ctampilkan,html.dark #csembunyikan{background:var(--hm-surface)}
.pesan-komentar{padding-left:16px;margin:0 0 12px}
/* C129 Notice overlay readability: labels render bright yellow and compact
   on photos (dark-navy 44px boxes were unreadable and cramped); titles
   clamp to 2 lines (the lead clamp lacked its display props, the smalls
   had none). Mobile white rows keep dark 44px labels. Scoped to the foto
   belt (Notice) only; the global label rules are untouched. */
.topik-foto .posttag a:nth-child(1){color:#fce44d;min-height:0;min-width:0}
.topikXML-leftfoto h3 a{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;text-overflow:ellipsis}
.topikXML-rightfoto h3 a{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;text-overflow:ellipsis}
@media (max-width:767px){
.topikXML-rightfoto .posttag a:nth-child(1){color:#3357a7;min-height:44px;min-width:44px}
}
/* C130 belt-card label density: the global 44px label box (C55 floor for
   rows) bloated compact belt cards (~18px dead space per row). Belt caption
   links go compact (WCAG inline-text exception, documented here); overlay
   belts go bright yellow like the foto belt. Mobile white rows keep dark
   44px (fotopopuler stays overlay on mobile, so it keeps yellow there).
   Scoped to belt patterns only; the global rule and its gate pins stand. */
.topikXML-left1 .posttag a:nth-child(1),.topikXML-right1 .posttag a:nth-child(1),.topikXML-left2 .posttag a:nth-child(1),.topikXML-right2 .posttag a:nth-child(1),.topikXML-left3 .posttag a:nth-child(1),.topikXML-right3 .posttag a:nth-child(1),#topikXML-leftvideo .posttag a:nth-child(1),#topikXML-rightvideo .posttag a:nth-child(1){min-height:0;min-width:0}/*BLGCHI001-C158: the two video exemptions above are corrected to the ID form the builder emits ('#topikXML-leftvideo/#topikXML-rightvideo'); the class form was dead, so the C55 44px label box survived on the Video side-cards and 3-line titles clipped at the 105px row. Live-verified on the served page: label box 44px -> 13px, 0/4 rows clipped (was 2/4).*/
.topikXML-leftfotopopuler .posttag a:nth-child(1),.topikXML-rightfotopopuler .posttag a:nth-child(1){color:#fce44d;min-height:0;min-width:0}
@media (max-width:767px){
.topikXML-left1 .posttag a:nth-child(1),.topikXML-right1 .posttag a:nth-child(1),.topikXML-left2 .posttag a:nth-child(1),.topikXML-right2 .posttag a:nth-child(1),.topikXML-left3 .posttag a:nth-child(1),.topikXML-right3 .posttag a:nth-child(1),.topikXML-leftvideo .posttag a:nth-child(1),.topikXML-rightvideo .posttag a:nth-child(1){color:#3357a7;min-height:44px;min-width:44px}
}
/* C131 headline slider jerk: the hero skeleton (16/9 capped at 420px) never
   matched the final .ct-wrapper (495px + 30px bottom margin), so every load
   jerked the homepage down when the News feed landed (measured 105px desktop,
   276px mobile). The skeleton now reserves the exact final box; mobile
   mirrors the mobile margin (auto = no bottom gap, like .ct-wrapper). Slides
   get a dark base so the swap reads calm, not a white flash. Scoped to the
   hero slot only; other skeletons untouched. */
.feed-slot[data-feed-callback="postarea4"] .hm-sk-hero{aspect-ratio:auto;height:495px;max-height:none}
.feed-slot[data-feed-callback="postarea4"] > div[aria-hidden="true"]{margin:0 auto 30px}
.slider-item{background:#111}
@media (max-width:767px){
.feed-slot[data-feed-callback="postarea4"] > div[aria-hidden="true"]{margin:auto}
}
/* C132 proper skeletons everywhere + enter transitions. Measured gaps: the
   related thumb-rows morphed into a text list (+545px), Latest Updates rows
   dwarfed their skeleton, foto stacked list rows for a grid (-250px), the
   video skeleton missed its ID selectors (stacked ~769px), tag rows jerked
   each popular item 51px staggered, next-article showed raw "Loading...", and
   every swap was instant. Skeletons now mirror final shapes (real li/ul/col
   classes where the belt uses them, so padding and chrome match by
   construction); every async insert rides one shared enter transition.
   C137: the transition animates the slot itself, never its children --
   the children form held an identity matrix on each belt column, which
   trapped the foto overlay smalls inside the wrong column. */
@keyframes hm-enter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.hm-enter{animation:hm-enter .28s ease both}
.hm-search-results li{animation:hm-enter .22s ease both}
@media (prefers-reduced-motion:reduce){.hm-enter,.hm-search-results li{animation:none}}
/* Belt calibration: fixed heroes match fixed finals (360/397/370); thumbs
   match final thumbs (100/112x80); cover cells match the overlay cards
   (260 fixed, foto 16/9 image-driven); the card2 body pad matches its
   card-body. Bars are empty blocks, so floated thumbs cover their underlap
   -- no BFC wrappers needed. Card3's 257x144 rule loses to the 100px rule
   (measured), so its skeleton rows are 100px side-rows like card2. */
.topikXML-left2 .hm-sk-hero{aspect-ratio:auto;height:360px;max-height:none}
#topikXML-leftvideo .hm-sk-hero{aspect-ratio:auto;height:397px;max-height:none}
.topikXML-leftfoto .hm-sk-hero{aspect-ratio:auto;height:370px;max-height:none}
.hm-sk-cbody{padding:24px}
.hm-sk-li{display:flex;gap:12px;align-items:center}
.hm-sk-t100{width:100px;height:100px;flex:0 0 100px}
.hm-sk-t80{width:112px;height:80px;flex:0 0 112px}
/* Foto smalls are image-driven 16/9 cells (no fixed CSS height), so the cover
   uses aspect-ratio and tracks any width; mobile rows mirror the 142x80
   white-row shape with text bars beside the thumb. */
.hm-sk-fcover{display:block;aspect-ratio:16/9}
.hm-sk-fbars{display:none}
.hm-sk-cover{display:block;height:260px}
.hm-sk-tagbar{display:block;height:44px}
.hm-sk-nextimg{float:left;width:257px;height:144px;margin:0 20px 0 0}
@media (max-width:767px){
#topikXML-leftvideo .hm-sk-hero{height:200px}
.hm-sk-nextimg{width:100px;height:100px;float:right;margin:0 0 0 12px}
.topikXML-rightfoto .hm-sk-fcover{aspect-ratio:auto;float:left;width:142px;height:80px;margin:0 12px 0 0}
.topikXML-rightfoto .hm-sk-fbars{display:block}
}
/* C133 card-label markers: the 7px \f0ca list glyph read as a broken box at
   caption size on every label row site-wide (measured live; the reference
   shares the flaw, improved deliberately). Small markers are a crisp CSS
   dash now -- font-independent, vertically centered in any row height via
   inline-block (the old float sat at the top of 44px rows). The legible 20px
   PP1 overlay icon is restored explicitly (the base swap would clear it);
   overlay markers match the yellow captions, with the mobile white-row dark
   restore mirroring C129. */
#PopularPosts1 .popular-tag::before{content:"\f0ca";font-family:FontAwesome;font-size:20px;width:auto;height:auto;background:none}
.topik-foto .posttag::before,.topikXML-leftfotopopuler .posttag::before,.topikXML-rightfotopopuler .posttag::before{color:#fce44d}
@media (max-width:767px){
.topikXML-rightfoto .posttag::before{color:#3357a7}
}
/* C206: Pages lists in the drawer, sidebar and footer */
#csssmenu .drawer-pages-title{display:block;line-height:40px;font-weight:400;font-size:16px;border-top:1px solid #e9ebee;margin:10px auto 0;padding:10px 20px 0}
#csssmenu .drawer-pages-title::before{content:"\f0ca";color:#3357a7;font-family:fontawesome;width:24px;display:inline-block;font-size:14px}
/* C211: the drawer Pages block collapses like the Categories block */
#csssmenu .drawer-pages-title{cursor:pointer}
#drawer-pages-toggle::after{content:"\f0dc";float:right;font-family:FontAwesome}
/* C212: the open Pages list lays out in two columns, matching Categories (#box) */
#drawer-pages-box ul{padding:0 0 10px 24px;overflow:hidden}
#drawer-pages-box ul li a{font-size:14px;line-height:30px;float:left;width:50%}
#csssmenu ul li.selected a{color:var(--hm-link)}
html.dark #csssmenu .drawer-pages-title{border-color:var(--hm-border)}
html.dark #csssmenu .drawer-pages-title::before{color:var(--hm-link)}
#sidebar-pages{margin:0 0 24px;padding:0 18px}
#sidebar-pages h2{font-size:20px;margin:0 0 6px;text-align:left}
#sidebar-pages ul{list-style:none;margin:0;padding:0}
#sidebar-pages li{border-bottom:1px solid #e9ebee}
#sidebar-pages li:last-child{border-bottom:0}
#sidebar-pages li a{display:block;padding:8px 0;font-size:14px}
#sidebar-pages li a:hover{color:var(--hm-link)}
#sidebar-pages li.selected a{color:var(--hm-link);font-weight:700}
html.dark #sidebar-pages li{border-color:var(--hm-border)}
#footer-right #PageList3{margin:16px 0}
/*BLGCHI001-C322: operator picked option C from the spacing mockup -- keep the
  separator dot but stop it reading as trailing padding. It is now a 4px circle
  placed in the middle of an 18px gap (not a glyph 5px after each label), rows
  are 10px apart, and the list is capped at 360px so the home column and the
  full-width single-page footer wrap alike. position:relative on the anchor is
  required: #footer-right is the positioned ancestor (C53), so without it the
  absolute dot escapes to the column edge.*/
#footer-right #PageList3 ul{display:flex;flex-wrap:wrap;justify-content:center;gap:10px 18px;margin:0 auto;padding:0;max-width:360px}#footer-right #PageList3 ul li{margin:0}
#footer-right #PageList3 li.selected a{color:#fff}
/*C217: "You might like" CTA card -- post recommendation with Download/Buy
  buttons. Label convention: dl:URL|filename and buy:URL|product-name on the
  post. All colours use --hm-* tokens so dark mode is automatic.*/
.hm-cta-card{border:1px solid var(--hm-border);border-radius:12px;background:var(--hm-surface);overflow:hidden;margin:0 0 18px}
.hm-cta-head{padding:12px 16px;font:700 15px/1 var(--hm-font);color:#fff;background:var(--hm-accent)}
html.dark .hm-cta-head{color:var(--hm-bg)}
.hm-cta-star{margin:0 4px 0 0}
.hm-cta-body{display:flex;gap:14px;padding:16px;align-items:flex-start}
.hm-cta-thumb{flex:0 0 auto;display:block;border-radius:8px;overflow:hidden;background:var(--hm-border)}
.hm-cta-thumb img{display:block;width:120px;height:120px;object-fit:cover}
.hm-cta-info{flex:1;min-width:0}
.hm-cta-title{font:700 17px/1.3 var(--hm-font);margin:0 0 6px}
.hm-cta-title a{color:var(--hm-text);text-decoration:none}
.hm-cta-title a:hover{color:var(--hm-link)}
.hm-cta-meta{font-size:13px;color:var(--hm-muted);line-height:1.4}
.hm-cta-author{font-weight:600}
.hm-cta-sep{margin:0 2px}
.hm-cta-actions{padding:0 16px 16px}
.hm-cta-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-top:1px solid var(--hm-border)}
.hm-cta-label{font:400 14px/1.4 var(--hm-font);color:var(--hm-muted);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.hm-cta-btn{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:8px 18px;border-radius:8px;font:700 14px/1 var(--hm-font);text-decoration:none;white-space:nowrap;flex:0 0 auto}
.hm-cta-btn-dl{background:var(--hm-accent);color:#fff}
html.dark .hm-cta-btn-dl{color:var(--hm-bg)}
.hm-cta-btn-dl:hover{filter:brightness(1.08)}
.hm-cta-btn-buy{background:#e60e35;color:#fff}
.hm-cta-btn-buy:hover{filter:brightness(1.08)}
.hm-cta-btn:focus-visible{outline:2px solid var(--hm-link);outline-offset:2px}
@media(max-width:600px){.hm-cta-body{flex-direction:column}.hm-cta-thumb img{width:100%;height:auto}}
/*C218: cookie consent banner -- fixed bottom bar with category checkboxes.
  Blocks third-party scripts (FB SDK, analytics) until consent is granted.
  Uses --hm-* tokens for dark mode. Mobile: stacks vertically.*/
.hm-consent{position:fixed;bottom:0;left:0;right:0;z-index:9999;background:var(--hm-surface);border-top:1px solid var(--hm-border);box-shadow:0 -4px 20px rgba(0,0,0,.15);padding:18px 20px;box-sizing:border-box;transform:translateY(100%);transition:transform .3s ease}
.hm-consent.hm-consent-show{transform:translateY(0)}
.hm-consent-inner{max-width:1100px;margin:0 auto}
.hm-consent-msg{font:400 14px/1.5 var(--hm-font);color:var(--hm-text);margin:0 0 12px}
.hm-consent-msg a{color:var(--hm-link)}
.hm-consent-cats{display:flex;flex-wrap:wrap;gap:14px;margin:0 0 14px}
.hm-consent-cat{display:flex;align-items:center;gap:6px;font:400 14px/1 var(--hm-font);color:var(--hm-text);cursor:pointer}
.hm-consent-cat input[type=checkbox]{width:18px;height:18px;margin:0;cursor:pointer}
.hm-consent-cat input[type=checkbox]:disabled{cursor:not-allowed;opacity:.6}
.hm-consent-cat label{cursor:pointer;user-select:none}
.hm-consent-cat input[type=checkbox]:disabled+label{cursor:not-allowed;opacity:.6}
.hm-consent-btns{display:flex;gap:10px;flex-wrap:wrap}
.hm-consent-btn{min-height:44px;padding:10px 20px;border-radius:8px;font:600 14px/1 var(--hm-font);cursor:pointer;border:1px solid var(--hm-border);background:var(--hm-bg);color:var(--hm-text)}
.hm-consent-btn:hover{background:var(--hm-border)}
.hm-consent-btn-primary{background:var(--hm-accent);color:#fff;border-color:var(--hm-accent)}
html.dark .hm-consent-btn-primary{color:var(--hm-bg)}
.hm-consent-btn-primary:hover{filter:brightness(1.08);background:var(--hm-accent)}
.hm-consent-btn:focus-visible{outline:2px solid var(--hm-link);outline-offset:2px}
@media(max-width:600px){.hm-consent-cats{flex-direction:column;gap:10px}.hm-consent-btns{flex-direction:column}.hm-consent-btn{width:100%}}
/*C219: comment embed styles -- responsive YouTube iframes and images in
  Blogger comments. Max-width 100%, aspect-ratio for video, border-radius,
  dark mode via --hm-* tokens.*/
.hm-cmt-embed{margin:12px 0;max-width:100%}
.hm-cmt-yt{position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;background:var(--hm-bg)}
.hm-cmt-yt iframe{position:absolute;top:0;left:0;width:100%;height:100%;border:0}
.hm-cmt-img{border-radius:8px;overflow:hidden;background:var(--hm-bg)}
.hm-cmt-img img{display:block;width:100%;height:auto;max-width:100%;border-radius:8px}
/*C220: shortcut keys help modal -- centered overlay with kbd styling, dark
  mode via --hm-* tokens. ESC or click outside closes.*/
.hm-shortcut-help{position:fixed;top:0;left:0;right:0;bottom:0;z-index:100000;background:rgba(0,0,0,.6);display:none;align-items:center;justify-content:center;padding:20px;box-sizing:border-box}
.hm-shortcut-help[aria-hidden='false']{display:flex}
.hm-shortcut-help-inner{background:var(--hm-surface);border-radius:12px;padding:24px;max-width:400px;width:100%;box-shadow:0 12px 40px rgba(0,0,0,.3)}
.hm-shortcut-help-title{font:700 18px/1.3 var(--hm-font);color:var(--hm-text);margin:0 0 16px}
.hm-shortcut-help-list{list-style:none;margin:0;padding:0}
.hm-shortcut-help-list li{display:flex;align-items:center;gap:12px;padding:8px 0;font:400 14px/1.4 var(--hm-font);color:var(--hm-text)}
.hm-shortcut-help-list kbd{display:inline-block;min-width:32px;padding:4px 8px;background:var(--hm-bg);border:1px solid var(--hm-border);border-radius:6px;font:600 13px/1 monospace;color:var(--hm-text);text-align:center}
.hm-shortcut-help-note{font:400 13px/1.4 var(--hm-font);color:var(--hm-muted);margin:16px 0 0}

b:if.script:
//
/* BLGCHI001-C67: the SafeLink generator -- customizable safe links with real
 * cryptography. The C62 base64 encoder stays as the fallback for browsers
 * without WebCrypto; both link kinds decode on this page. C329 retouches the
 * UX around it: grouped fields with live hints, a chip-based result panel, a
 * cancellable countdown, clipboard-first copy and focus management. NOTHING
 * about the link format changes -- old links decode exactly as before.
 *
 * b64 helpers exist because window.btoa and atob are ASCII-ONLY and throw on
 * anything above U+00FF, while a URL may legitimately carry a non-ASCII path.
 * Text runs through UTF-8 bytes first; TextEncoder is the supported route.
 *
 * The alphabet is base64URL: + and / become - and _, padding is dropped. In
 * a query string the standard alphabet is a liability -- + decodes to a space
 * and a stray / reads as a path separator. base64URL survives pasting.
 *
 * Cryptography: AES-GCM-256. The key either travels in the link fragment
 * (convenient; anyone holding the link can open it) or is derived from a
 * visitor-typed password with PBKDF2 (the link alone opens nothing). GCM
 * authenticates, so a tampered link fails closed instead of opening garbage.
 * A fragment (#k=) is never sent to any server -- not even this blog's.
 */
(function () {
  'use strict';

  function utf8ToBytes(str) {
    if (window.TextEncoder) { return new TextEncoder().encode(str); }
    var out = [], i, c;
    for (i = 0; i < str.length; i++) {
      c = str.charCodeAt(i);
      if (c < 128) { out.push(c); }
      else if (c < 0x800) { out.push(192 | (c >> 6), 128 | (c & 63)); }
      else { out.push(224 | (c >> 12), 128 | ((c >> 6) & 63), 128 | (c & 63)); }
    }
    return new Uint8Array(out);
  }

  function bytesToUtf8(bytes) {
    if (window.TextDecoder) { return new TextDecoder().decode(bytes); }
    var s = '', i;
    for (i = 0; i < bytes.length; i++) { s += String.fromCharCode(bytes[i]); }
    return decodeURIComponent(escape(s));
  }

  function toB64Url(str) {
    var bytes = utf8ToBytes(str), bin = '', i;
    for (i = 0; i < bytes.length; i++) { bin += String.fromCharCode(bytes[i]); }
    return window.btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  function fromB64Url(s) {
    var b = String(s).replace(/-/g, '+').replace(/_/g, '/');
    while (b.length % 4) { b += '='; }
    return bytesToUtf8(new Uint8Array(window.atob(b).split('').map(function (c) { return c.charCodeAt(0); })));
  }

  function bytesToB64(bytes) {
    var bin = '', i;
    for (i = 0; i < bytes.length; i++) { bin += String.fromCharCode(bytes[i]); }
    return window.btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  function b64ToBytes(s) {
    var b = String(s).replace(/-/g, '+').replace(/_/g, '/');
    while (b.length % 4) { b += '='; }
    var raw = window.atob(b), out = new Uint8Array(raw.length), i;
    for (i = 0; i < raw.length; i++) { out[i] = raw.charCodeAt(i); }
    return out;
  }

  /* The security gate. Everything above is convenience; this is the feature.
   *
   * new URL() THROWS on input it cannot parse, which is the behaviour wanted: a
   * malformed target produces null rather than a best guess. It also normalises
   * the scheme to lowercase, so JaVaScRiPt: is rejected exactly like
   * javascript:. Only two schemes survive the comparison below.
   */
  function safeTarget(raw) {
    var u;
    try { u = new URL(String(raw)); } catch (e) { return null; }
    if (u.protocol !== 'http:' && u.protocol !== 'https:') { return null; }
    return u.href;
  }

  // A destination equal to THIS page would make the sealed link decode into
  // the generator again -- an airlock that opens into itself. The C64 minting
  // rule already aims every generated link back at this page; pasting that
  // address (or this page's plain URL) back in as a destination is always a
  // mistake, so the generator refuses it up front. Homepage, posts, labels
  // and search pages sit on other paths and stay legal.
  function selfDestination(href) {
    var u;
    try { u = new URL(href); } catch (e) { return false; }
    var l = window.location;
    return u.origin === l.origin && u.pathname === l.pathname;
  }

  // The link points back at THIS page (origin + full path), never at a
  // hardcoded slug: Blogger mints suffixed page URLs whenever the clean slug
  // is reserved by a trashed page, and a hardcoded slug generates links that
  // 404 on follow (measured on the live blog). The decoder reads the query
  // string wherever it runs, so a self-URL link always resolves.
  function selfLink(h) {
    var l = window.location;
    return l.origin + l.pathname + '?d=' + toB64Url(h);
  }

  function selfLinkX(tok) {
    var l = window.location;
    return l.origin + l.pathname + '?x=' + tok;
  }

  function hasCrypto() {
    return !!(window.crypto && window.crypto.subtle && window.TextEncoder && window.crypto.getRandomValues);
  }

  function rand(n) {
    var b = new Uint8Array(n);
    window.crypto.getRandomValues(b);
    return b;
  }

  function importAes(raw, usages) {
    return window.crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, usages);
  }

  function passwordKey(pw, salt) {
    return window.crypto.subtle.importKey('raw', utf8ToBytes(pw), { name: 'PBKDF2' }, false, ['deriveKey']).then(function (base) {
      return window.crypto.subtle.deriveKey({ name: 'PBKDF2', salt: salt, iterations: 100000, hash: 'SHA-256' }, base, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
    });
  }

  // Package shape: 1.<salt>.<iv>.<ciphertext>, every part base64URL. Salt
  // travels outside the ciphertext so a password can be stretched on open;
  // in key mode the salt is random padding the opener ignores.
  function seal(pkg, key, salt) {
    var iv = rand(12);
    return window.crypto.subtle.encrypt({ name: 'AES-GCM', iv: iv }, key, utf8ToBytes(JSON.stringify(pkg))).then(function (ct) {
      return '1.' + bytesToB64(salt) + '.' + bytesToB64(iv) + '.' + bytesToB64(new Uint8Array(ct));
    });
  }

  function unseal(token, key) {
    var parts = String(token).split('.');
    if (parts.length !== 4 || parts[0] !== '1') { return Promise.reject(new Error('shape')); }
    var iv, ct;
    try { iv = b64ToBytes(parts[2]); ct = b64ToBytes(parts[3]); }
    catch (e) { return Promise.reject(e); }
    return window.crypto.subtle.decrypt({ name: 'AES-GCM', iv: iv }, key, ct).then(function (pt) {
      return JSON.parse(bytesToUtf8(new Uint8Array(pt)));
    });
  }

  function pkgSalt(x) {
    try { return b64ToBytes(String(x).split('.')[1]); }
    catch (e) { return null; }
  }

  function fragKey() {
    var m = /[#&]k=([A-Za-z0-9\-_]+)/.exec(window.location.hash || '');
    if (!m) { return null; }
    try { return importAes(b64ToBytes(m[1]), ['decrypt']); }
    catch (e) { return null; }
  }

  function showError(msg) {
    var e = document.getElementById('sl-err');
    if (!e) { return; }
    e.setAttribute('role', 'alert');
    e.textContent = msg;
    e.hidden = false;
  }

  function byId(id) { return document.getElementById(id); }

  // --- C329 UX helpers -------------------------------------------------------

  // The invalid-destination flag drives the red border through an attribute
  // selector, so the body keeps carrying ids only -- no styling classes.
  function setInvalid(on) {
    var i = byId('sl-url');
    if (!i) { return; }
    if (on) { i.setAttribute('aria-invalid', 'true'); }
    else { i.removeAttribute('aria-invalid'); }
  }

  // Bring a just-revealed panel into view without yanking the page under a
  // visitor who asked the OS to calm motion down.
  function reveal(el) {
    var still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    try { el.scrollIntoView({ block: 'nearest', behavior: still ? 'auto' : 'smooth' }); } catch (e) {}
  }

  // A landing page waits for the visitor's own click, and a no-wait link has
  // no timer to end -- in either case the affected option has nothing to act
  // on: disable the field and say why, instead of ignoring it silently.
  function syncWait() {
    var mode = byId('sl-mode'), count = byId('sl-count'), hint = byId('sl-hint-wait'),
        end = byId('sl-end'), endHint = byId('sl-hint-end');
    if (!mode || !count) { return; }
    var land = mode.value === 'land';
    count.disabled = land;
    if (hint) { hint.hidden = !land; }
    if (end) {
      var n = parseInt(count.value, 10);
      var off = land || !(n === 3 || n === 5 || n === 10);
      end.disabled = off;
      if (endHint) { endHint.hidden = !off; }
    }
  }

  // The result panel states the link's kind and behaviour as chips: one glance
  // answers "what happens when someone opens this".
  function metaChips(kind, pkg) {
    var chips = [];
    if (kind === 'plain') {
      chips.push('Plain base64: hides the text, not the click');
      chips.push('Options need encryption, which this browser cannot do');
      return chips;
    }
    chips.push(kind === 'password' ? 'Password protected' : 'Encrypted: AES key rides in the link');
    chips.push(pkg.m === 'land' ? 'Landing page first' : (pkg.c > 0 ? (pkg.x === 'click' ? 'Waits ' + pkg.c + ' seconds, then an Open button' : 'Waits ' + pkg.c + ' seconds, then continues') : 'Continues immediately'));
    chips.push(pkg.e ? 'Expires ' + new Date(pkg.e).toLocaleString() : 'Never expires');
    return chips;
  }

  function showResult(url, href, chips) {
    var link = byId('sl-link'), test = byId('sl-test'), dest = byId('sl-dest'),
        metaEl = byId('sl-meta'), out = byId('sl-out');
    if (!link || !test || !dest || !metaEl || !out) { return; }
    link.value = url;
    test.href = url;
    // Text nodes, not innerHTML: the address is validated, but the page never
    // has to trust that a URL cannot carry markup.
    dest.textContent = 'Points to ';
    var code = document.createElement('code');
    code.textContent = href;
    dest.appendChild(code);
    while (metaEl.firstChild) { metaEl.removeChild(metaEl.firstChild); }
    chips.forEach(function (c) {
      var s = document.createElement('span');
      s.textContent = c;
      metaEl.appendChild(s);
    });
    out.hidden = false;
    reveal(out);
  }

  // --- decoder path (legacy base64) -----------------------------------------
  function runDecoder(d) {
    var target = null, why = '',
        gen = byId('sl-gen'),
        gp = byId('sl-go-page'),
        msg = byId('sl-go-msg');
    if (!gen || !gp || !msg) { return; }
    gen.hidden = true;
    gp.hidden = false;
    gp.focus();
    try {
      target = safeTarget(fromB64Url(d));
    } catch (err) {
      why = 'This link is damaged or was cut short when it was copied.';
    }
    if (!target) {
      if (!why) {
        why = 'This link does not point to a web page. Only http and https links can be followed.';
      }
      msg.textContent = why;
      return;
    }
    msg.textContent = 'Taking you to ' + target;
    window.location.replace(target);
  }

  // --- decoder path (encrypted) -----------------------------------------------
  function goMessage() { return byId('sl-go-msg'); }

  function openWithKey(x, key, onFail) {
    unseal(x, key).then(function (pkg) { renderGo(pkg); }, function () { onFail(); });
  }

  function showUnlock(x) {
    var msg = goMessage(), unlock = byId('sl-unlock'), key = byId('sl-key'), open = byId('sl-open');
    if (msg) { msg.textContent = 'This link is password protected.'; }
    if (!unlock || !key || !open) { return; }
    unlock.hidden = false;
    key.focus();
    open.onclick = function () {
      var salt = pkgSalt(x);
      if (!salt || !key.value) {
        if (msg) { msg.textContent = 'Type the password this link was created with.'; }
        return;
      }
      passwordKey(key.value, salt).then(function (kk) {
        openWithKey(x, kk, function () {
          if (msg) { msg.textContent = 'Wrong password, or the link is damaged.'; }
        });
      }, function () {
        if (msg) { msg.textContent = 'Wrong password, or the link is damaged.'; }
      });
    };
    key.onkeydown = function (ev) {
      if (ev.key === 'Enter') { ev.preventDefault(); open.click(); }
    };
  }

  function runCryptoDecoder(x) {
    var gen = byId('sl-gen'), gp = byId('sl-go-page'), msg = goMessage();
    if (!gen || !gp || !msg) { return; }
    gen.hidden = true;
    gp.hidden = false;
    gp.focus();
    if (!hasCrypto()) {
      msg.textContent = 'This link is encrypted, but this browser cannot do the cryptography. Open it in a current browser over https.';
      return;
    }
    var kp = fragKey();
    if (kp) {
      kp.then(function (key) {
        openWithKey(x, key, function () { showUnlock(x); });
      }, function () { showUnlock(x); });
    } else {
      showUnlock(x);
    }
  }

  function renderGo(pkg) {
    var msg = goMessage();
    if (!msg) { return; }
    var target = safeTarget(pkg.u || '');
    if (!target) {
      msg.textContent = 'This link does not point to a web page. Only http and https links can be followed.';
      return;
    }
    if (pkg.e && Date.now() > pkg.e) {
      msg.textContent = 'This link has expired. Ask the sender for a fresh one.';
      return;
    }
    var title = String(pkg.t || ''), note = String(pkg.n || '');
    if (pkg.m === 'land') {
      var lt = byId('sl-land-title'), ln = byId('sl-land-note'),
          lh = byId('sl-land-host'), go = byId('sl-land-go'), land = byId('sl-land');
      if (!lt || !ln || !lh || !go || !land) { return; }
      msg.textContent = title || 'A safe link brought you here.';
      // Text nodes, not innerHTML: titles and notes are sender-controlled.
      lt.textContent = title || 'Continue to an external page';
      ln.textContent = note;
      try { lh.textContent = 'Continues to ' + new URL(target).hostname; }
      catch (e) { lh.textContent = target; }
      go.href = target;
      go.textContent = 'Continue';
      land.hidden = false;
      go.focus();
      return;
    }
    msg.textContent = title ? title : 'Taking you to ' + target;
    var wait = pkg.c > 0 ? pkg.c : 0;
    if (wait > 0) { startCountdown(target, wait, pkg.x === 'click', title); }
    else { window.location.replace(target); }
  }

  // The countdown is cancellable: a visitor mid-read is not a failure, and
  // trapping them in a redirect they cannot stop was the C67 behaviour's one
  // hostile edge. Cancel stops the timer and hands control back with a
  // Continue-now button. And since C332 the link's creator chooses how the
  // timer ends: an Open button the visitor presses (no redirect they did not
  // ask for), or the automatic continue. Links sealed before the choice carry
  // no x in their package and keep the automatic redirect. A missing wait
  // line (stale body) degrades to the old unstoppable countdown rather than
  // breaking.
  function startCountdown(target, seconds, openButton, title) {
    var w = byId('sl-wait'), num = byId('sl-count-num'),
        cancel = byId('sl-cancel'), goNow = byId('sl-continue'), timer = null;
    if (!w || !num) { window.location.replace(target); return; }
    var left = seconds;
    function navigate() {
      if (timer) { window.clearInterval(timer); timer = null; }
      window.location.replace(target);
    }
    function showEndState() {
      if (timer) { window.clearInterval(timer); timer = null; }
      // The line spent the countdown promising "Continuing in N seconds";
      // re-label its leading text node (no innerHTML) so the close never
      // ends on a promise the link no longer performs, then retire it.
      if (w.firstChild && w.firstChild.nodeValue) {
        w.firstChild.nodeValue = w.firstChild.nodeValue.replace('Continuing in ', 'Ready in ');
      }
      w.hidden = true;
      if (cancel) { cancel.hidden = true; }
      if (goNow) {
        goNow.textContent = 'Open the page';
        goNow.hidden = false;
        goNow.onclick = navigate;
        goNow.focus();
      }
      var msg = goMessage();
      if (msg) { msg.textContent = title ? title + ' is ready.' : 'Done - the page is ready.'; }
    }
    function finish() {
      if (openButton) { showEndState(); } else { navigate(); }
    }
    if (cancel) {
      cancel.hidden = false;
      cancel.onclick = function () {
        if (timer) { window.clearInterval(timer); timer = null; }
        w.hidden = true;
        cancel.hidden = true;
        if (goNow) {
          goNow.hidden = false;
          goNow.onclick = navigate;
        }
        var msg = goMessage();
        if (msg) { msg.textContent = 'Cancelled. Press Continue now when you are ready.'; }
      };
    }
    w.hidden = false;
    num.textContent = String(left);
    timer = window.setInterval(function () {
      left -= 1;
      if (left <= 0) { finish(); return; }
      num.textContent = String(left);
    }, 1000);
  }

  // --- generator path ---------------------------------------------------------
  function fieldVal(id) {
    var el = byId(id);
    return el ? el.value : '';
  }

  function waitSecs() {
    var n = parseInt(fieldVal('sl-count'), 10);
    return (n === 3 || n === 5 || n === 10) ? n : 0;
  }

  function expMs() {
    var v = fieldVal('sl-exp');
    return (v === '3600000' || v === '86400000' || v === '604800000' || v === '2592e6') ? Number(v) : 0;
  }

  function buildPlain(href) {
    showResult(selfLink(href), href, metaChips('plain'));
  }

  function buildCrypto(href, opts) {
    var salt = rand(16);
    var pkg = { v: 1, u: href, t: opts.title, n: opts.note, m: opts.mode, c: opts.wait, e: opts.expMs ? Date.now() + opts.expMs : 0 };
    // The timer-end choice rides only when it actually changes the old
    // default: a wait that ends in an Open button instead of the automatic
    // redirect. JSON drops the undefined key, so links sealed before this
    // choice existed carry no x and decode as the automatic continue --
    // every old link keeps behaving exactly as it always did.
    if (opts.mode === 'go' && opts.wait > 0 && opts.end === 'click') { pkg.x = 'click'; }
    function fail(msg) {
      var out = byId('sl-out');
      if (out) { out.hidden = true; }
      showError(msg);
    }
    function done(key, frag) {
      seal(pkg, key, salt).then(function (tok) {
        showResult(selfLinkX(tok) + frag, href, metaChips(opts.pw ? 'password' : 'key', pkg));
      }, function () {
        fail('The browser could not encrypt. Try again.');
      });
    }
    if (opts.pw) {
      passwordKey(opts.pw, salt).then(function (k) { done(k, ''); }, function () {
        fail('The browser could not use that password.');
      });
    } else {
      var raw = rand(32);
      importAes(raw, ['encrypt', 'decrypt']).then(function (k) { done(k, '#k=' + bytesToB64(raw)); }, function () {
        fail('The browser could not encrypt. Try again.');
      });
    }
  }

  function legacyCopy(link) {
    link.focus();
    link.select();
    try { document.execCommand('copy'); } catch (e) {}
  }

  function initGenerator() {
    var input = byId('sl-url'),
        go = byId('sl-go'),
        out = byId('sl-out');
    if (!input || !go || !out) { return; }
    function build() {
      var e = byId('sl-err');
      var href = safeTarget(input.value.trim());
      if (!href) {
        out.hidden = true;
        setInvalid(true);
        showError('That is not a web address. Paste a full link beginning with http:// or https://.');
        return;
      }
      if (selfDestination(href)) {
        out.hidden = true;
        setInvalid(true);
        showError('That is this SafeLink page itself - the link would come straight back here. Paste the page you want to protect instead: a post, category, search page or the homepage.');
        return;
      }
      setInvalid(false);
      if (e) { e.hidden = true; }
      var land = fieldVal('sl-mode') === 'land';
      var opts = {
        title: fieldVal('sl-title').trim(),
        note: fieldVal('sl-note').trim(),
        mode: land ? 'land' : 'go',
        wait: land ? 0 : waitSecs(),
        end: fieldVal('sl-end'),
        expMs: expMs(),
        pw: fieldVal('sl-pass')
      };
      if (!hasCrypto()) { buildPlain(href); return; }
      buildCrypto(href, opts);
    }
    go.addEventListener('click', build);
    input.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter') { ev.preventDefault(); build(); }
    });
    input.addEventListener('input', function () { setInvalid(false); });
    ['sl-title', 'sl-note', 'sl-pass'].forEach(function (id) {
      var el = byId(id);
      if (el) {
        el.addEventListener('keydown', function (ev) {
          if (ev.key === 'Enter') { ev.preventDefault(); build(); }
        });
      }
    });
    var mode = byId('sl-mode'), countSel = byId('sl-count');
    if (mode) { mode.addEventListener('change', syncWait); }
    if (countSel) { countSel.addEventListener('change', syncWait); }
    syncWait();
    var copy = byId('sl-copy'), link = byId('sl-link');
    if (copy && link) {
      link.addEventListener('focus', function () { link.select(); });
      copy.addEventListener('click', function () {
        function done() {
          copy.textContent = 'Copied';
          window.setTimeout(function () { copy.textContent = 'Copy'; }, 1600);
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(link.value).then(done, function () { legacyCopy(link); done(); });
        } else {
          legacyCopy(link);
          done();
        }
      });
    }
  }

  function boot() {
    var q;
    try { q = new URLSearchParams(window.location.search); }
    catch (e) { initGenerator(); return; }
    var x = q.get('x'), d = q.get('d');
    if (x) { runCryptoDecoder(x); }
    else if (d) { runDecoder(d); }
    else { initGenerator(); }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
//

body.script:
/*BLGCHI001-C218: cookie consent -- shows banner if no consent stored, saves
  preferences to localStorage, provides hmConsent.check(category) API for
  third-party scripts to check before loading. Necessary category is always
  granted. Functional/Analytics/Marketing require explicit consent.*/
(function(){
  var STORAGE_KEY='hm-consent';
  var banner=document.getElementById('hm-consent');
  if(!banner)return;
  var acceptBtn=document.getElementById('hm-consent-accept');
  var saveBtn=document.getElementById('hm-consent-save');
  var functional=document.getElementById('hm-consent-functional');
  var analytics=document.getElementById('hm-consent-analytics');
  var marketing=document.getElementById('hm-consent-marketing');
  function getConsent(){
    try{var raw=localStorage.getItem(STORAGE_KEY);return raw?JSON.parse(raw):null;}catch(e){return null;}
  }
  function saveConsent(state){
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}
    banner.classList.remove('hm-consent-show');
    banner.setAttribute('aria-hidden','true');
    window.dispatchEvent(new CustomEvent('hm-consent-change',{detail:state}));
  }
  function showBanner(){
    banner.classList.add('hm-consent-show');
    banner.setAttribute('aria-hidden','false');
  }
  function loadConsent(){
    var saved=getConsent();
    if(saved){
      functional.checked=!!saved.functional;
      analytics.checked=!!saved.analytics;
      marketing.checked=!!saved.marketing;
      return true;
    }
    return false;
  }
  if(!loadConsent())showBanner();
  acceptBtn.addEventListener('click',function(){
    saveConsent({necessary:true,functional:true,analytics:true,marketing:true});
  });
  saveBtn.addEventListener('click',function(){
    saveConsent({
      necessary:true,
      functional:functional.checked,
      analytics:analytics.checked,
      marketing:marketing.checked
    });
  });
  window.hmConsent={
    check:function(cat){
      if(cat==='necessary')return true;
      var saved=getConsent();
      return saved&&!!saved[cat];
    }
  };
})();

