the request off. Same selectors, same thumbnail-size rewrite. BLGCHI001-C132: the link carries a matching skeleton instead of raw Loading text (mirrors .article-img both widths); the preview transitions in, and a failed fetch clears instead of stranding the shimmer. */
(function(){var target=document.querySelector('.next-article .blog-pager-newer-link');if(!target)return;var href=target.getAttribute("href");if(!href){target.closest(".next-article").style.display="none";return;}fetch(href,{credentials:"same-origin"}).then(function(r){return r.ok?r.text():null}).then(function(txt){if(!txt){target.innerHTML="";return;}var doc=new DOMParser().parseFromString(txt,"text/html");var tEl=doc.querySelector('.post .post-title');var title=tEl?tEl.textContent:"";var body=doc.querySelector('.post .post-body');var bImg=body&&body.querySelector('img');var sImg=null;if(body){var sep=body.querySelector('.separator img');var fig=body.querySelector('figure img');var td=body.querySelector('td img');sImg=sep||fig||td}var im=bImg||sImg;var img=im?(im.getAttribute("src")||""):"";var lEl=doc.getElementById("post-labels-bawah");var labels=lEl?lEl.innerHTML:"";if(!img){img='data:image/svg+xml,%3Csvg%0Axmlns=%22http:%2F%2Fwww.w3.org%2F2000%2Fsvg%22%0AviewBox=%220%0A0%0A320%0A180%22%0ApreserveAspectRatio=%22xMidYMid%0Aslice%22%3E%3Cdefs%3E%3ClinearGradient%0Aid=%22a%22%0Ax1=%220%22%0Ay1=%220%22%0Ax2=%221%22%0Ay2=%221%22%3E%3Cstop%0Aoffset=%220%22%0Astop-color=%22%233357a7%22%2F%3E%3Cstop%0Aoffset=%221%22%0Astop-color=%22%231976d2%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Crect%0Awidth=%22320%22%0Aheight=%22180%22%0Afill=%22url%28%23a%29%22%2F%3E%3Cg%0Afill=%22none%22%0Astroke=%22%23fff%22%0Astroke-opacity=%22.5%22%0Astroke-width=%227%22%0Astroke-linecap=%22round%22%0Astroke-linejoin=%22round%22%3E%3Crect%0Ax=%22102%22%0Ay=%2252%22%0Awidth=%22116%22%0Aheight=%2276%22%0Arx=%229%22%2F%3E%3Ccircle%0Acx=%22134%22%0Acy=%2281%22%0Ar=%227%22%2F%3E%3Cpath%0Ad=%22M106%0A117l24-26%0A18%0A18%0A22-28%0A44%0A34%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E'}else{img=img.replace(/\/([chswp]\d+)(\-[chswp]\d+)*(\-[cp])?\//g,'/w257-h144-c/')}
labels=labels.replace(/<\/a>/g,'</em>').replace(/<a(\s[^>]*)?>/g,'<em>').replace(/&nbsp;/g,' ').replace(/>\s+/g,'>').replace(/\s+</g,'<').trim();target.innerHTML='<div class="article-img"><img alt="'+title+'" src="'+img+'"></div><div class="article-title">'+'<small>'+labels+'</small>'+''+title+'</div>';target.closest(".next-article").classList.add("hm-enter");}).catch(function(){target.innerHTML="";})})();
