div.script:
//
var ry='<h2><span>Recommended</span><div class="h2border-img"></div></h2>',rn="<h2>No Recommendations</h2>",rcomment="comments",rdisable="disable comments",commentYN="no",dw="",titles=[],labels=[],titlesNum=0,urls=[],timeR=[],thumb=[],commentsNum=[],comments=[],maxresults=8;function related_results_labels(e){for(var t=0;t<e.feed.entry.length;t++){var l=e.feed.entry[t];titles[titlesNum]=l.title.$t,labels[titlesNum]=l.category;for(var s=0;s<l.link.length;s++)if(commentsNum[titlesNum]="thr$total"in l?l.thr$total.$t+" "+rcomment:rdisable,"alternate"==l.link[s].rel){urls[titlesNum]=l.link[s].href,timeR[titlesNum]=l.published.$t,thumb[titlesNum]="media$thumbnail"in l?l.media$thumbnail.url:"data:image/svg+xml,%3Csvg%0Axmlns=%22http:%2F%2Fwww.w3.org%2F2000%2Fsvg%22%0AviewBox=%220%0A0%0A320%0A180%22%0ApreserveAspectRatio=%22xMidYMid%0Aslice%22%3E%3Cdefs%3E%3ClinearGradient%0Aid=%22a%22%0Ax1=%220%22%0Ay1=%220%22%0Ax2=%221%22%0Ay2=%221%22%3E%3Cstop%0Aoffset=%220%22%0Astop-color=%22%233357a7%22%2F%3E%3Cstop%0Aoffset=%221%22%0Astop-color=%22%231976d2%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Crect%0Awidth=%22320%22%0Aheight=%22180%22%0Afill=%22url%28%23a%29%22%2F%3E%3Cg%0Afill=%22none%22%0Astroke=%22%23fff%22%0Astroke-opacity=%22.5%22%0Astroke-width=%227%22%0Astroke-linecap=%22round%22%0Astroke-linejoin=%22round%22%3E%3Crect%0Ax=%22102%22%0Ay=%2252%22%0Awidth=%22116%22%0Aheight=%2276%22%0Arx=%229%22%2F%3E%3Ccircle%0Acx=%22134%22%0Acy=%2281%22%0Ar=%227%22%2F%3E%3Cpath%0Ad=%22M106%0A117l24-26%0A18%0A18%0A22-28%0A44%0A34%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E",titlesNum++;break}}}function removeRelatedDuplicates(){for(var e=[],t=[],l=[],s=[],i=[],r=[],n=0;n<urls.length;n++)contains(e,urls[n])||(e.length+=1,e[e.length-1]=urls[n],t.length+=1,t[t.length-1]=titles[n],l.length+=1,l[l.length-1]=labels[n],s.length+=1,s[s.length-1]=timeR[n],i.length+=1,i[i.length-1]=thumb[n],r.length+=1,r[r.length-1]=commentsNum[n]);urls=e,titles=t,labels=l,timeR=s,thumb=i,commentsNum=r}function contains(e,t){for(var l=0;l<e.length;l++)if(e[l]==t)return!0;return!1}function printRelatedLabels(e){var t=e.indexOf("?m=0");-1!=t&&(e=e.replace(/\?m=0/g,""));for(var l=0;l<urls.length;l++)urls[l]==e&&(urls.splice(l,1),titles.splice(l,1),labels.splice(l,1),timeR.splice(l,1),thumb.splice(l,1),commentsNum.splice(l,1));var s=Math.floor((titles.length-1)*Math.random()),l=0;if(0==titles.length)dw+=rn;else{for(dw+=ry,dw+='<div class="clear"/></div><ul>';l<titles.length&&l<20&&l<maxresults;){var i=timeR[s].split("T")[0].split("-");-1!=t&&(urls[s]=urls[s]+"?m=0"),comments[s]="yes"==commentYN?" - "+commentsNum[s]:"",dw+='<li class="related-post"><a href="'+urls[s]+'" rel="dofollow" aria-label="'+titles[s].replace(/"/g,"&quot;")+'"></a><div class="related-body"><div class="related-tag1">'+(labels[s]||[]).map(function(e){return"<span>"+e.term+"</span>"}).join(" ")+'</div><div class="related-post-title"><a href="'+urls[s]+'" rel="dofollow">'+titles[s]+'</a></div><time datetime="'+timeR[s]+'">'+i[2]+" "+["","January","February","March","April","May","June","July","August","September","October","November","December"][+i[1]]+" "+i[0]+"</time></div></li></div>",s<titles.length-1?s++:s=0,l++}dw+="</ul>"}urls.splice(0,urls.length),titles.splice(0,titles.length),document.getElementById("related-posts").innerHTML=dw}
//

//
(function(){
  /*BLGCHI001-C28 (B2): the label feeds run in parallel instead of the serial
    json-in-script script chain they replace; printRelatedLabels fires once the
    join settles, so the render still sees every label's entries. A failed or
    empty label feed contributes nothing but still counts down; the direct
    data-post-url read replaces the parser-ordered inline kick. The hidden
    per-label inputs cannot be observed individually, so the related block
    itself is the observed element and its labels fetch together when it
    nears the viewport (C15 discipline: nothing below the fold is fetched
    upfront).*/
  var box=document.getElementById("related-posts");
  if(!box)return;
  var postUrl=box.getAttribute("data-post-url")||"";
  var inputs=box.querySelectorAll("[data-feed]");
  var pending=inputs.length;
  function finish(){
    removeRelatedDuplicates();
    printRelatedLabels(postUrl);
    box.classList.add("hm-enter");
  }
  function settled(){if(--pending===0)finish();}
  function collect(input){
    fetch(input.getAttribute("data-feed"),{credentials:"same-origin"})
      .then(function(r){return r.ok?r.json():null;})
      .then(function(json){try{if(json&&json.feed&&json.feed.entry)related_results_labels(json);}catch(e){}})
      .catch(function(){})
      .then(settled);
  }
  function start(){
    /*BLGCHI001-C132: the old thumb-rows morphed into a text list (+545px).
      The skeleton is the list now: the real heading plus text rows in the
      real ul/li classes, so chrome matches by construction. Five rows is the
      middle of the 0-8 range (the count is unknowable before the fetch).*/
    if(pending){var sk='<h2><span>Recommended</span><div class="h2border-img"></div></h2><ul aria-hidden="true">';for(var q=0;q<5;q++)sk+='<li class="related-post"><div class="related-body hm-sk-textrow"><span class="hm-sk hm-sk-bar-s"></span><span class="hm-sk hm-sk-bar"></span><span class="hm-sk hm-sk-bar"></span></div></li>';box.innerHTML=sk+'</ul>';}
    for(var i=0;i<inputs.length;i++)collect(inputs[i]);
  }
  if(!pending){finish();return;}
  if("IntersectionObserver" in window){
    var rio=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){rio.unobserve(e.target);start();}});},{rootMargin:"200px 0px"});
    rio.observe(box);
  }else{start();}
})();
//

b:if.script:
 //
/*BLGCHI001-C350: comments collapse toggle -- same single-slot +/- feature as the post-bottom Trending box (one of the pair visible at a time, box open by default). Rows are the disclaimer plus the native comments box; re-queried on every paint so late-rendered nodes join. No < or && below keeps the inline script XML-clean.*/
(function(){function rows(){var t=document.getElementById('fbcomment-title');if(!t||!t.parentNode)return [];return document.querySelectorAll('.pesan-komentar,.comments');}function bind(){var sh=document.getElementById('ctampilkan');var hd=document.getElementById('csembunyikan');if(!sh||!hd)return false;if(sh.getAttribute('data-hm-bound')==='1')return true;sh.setAttribute('data-hm-bound','1');var open=true;function paint(){rows().forEach(function(r){r.style.display=open?'':'none';});sh.style.display=open?'none':'';hd.style.display=open?'':'none';sh.setAttribute('aria-expanded',open?'true':'false');hd.setAttribute('aria-expanded',open?'true':'false');}sh.addEventListener('click',function(){open=true;paint();});hd.addEventListener('click',function(){open=false;paint();});paint();return true;}if(!bind()){document.addEventListener('DOMContentLoaded',bind);}})();
//

 //
/*BLGCHI001-C170: comment total counter -- the h4 and the collapsed-toggle badge show top-level + replies. Blogger has no per-branch size accessor, so count the rendered list (top items + nested thread items); a MutationObserver recounts late renders and Load more appends. Server label stands when no list rendered (non-embedded). No < or && below keeps the inline script XML-clean.*/
(function(){/*BLGCHI001-C184 (B75): the badge ticked through every intermediate total while comments streamed in (one paint per observer batch). Trending writes once, so now the badge writes once too: paintCount records n and rearms a 500ms quiet timer, paintBadge writes the settled total. h4 and aria-label stay live.*/var hmBadgeN=0;var hmBadgeT=null;function paintBadge(){hmBadgeT=null;var badge=document.getElementById('comment-count');if(!badge){return;}if(hmBadgeN>0){badge.style.display='';if(badge.textContent!==String(hmBadgeN)){badge.textContent=hmBadgeN;}}else{badge.style.display='none';}}function paintCount(){var holder=document.getElementById('comment-holder');var thread=holder?holder.querySelector('.toplevel-thread'):null;var top=thread?thread.querySelectorAll(':scope>ol>li.comment').length:0;var nested=holder?holder.querySelectorAll('ol.thread-chrome li.comment').length:0;var n=top+nested;var h4=document.querySelector('#comments h4');if(h4){if(thread){var label;if(n===0){label='No comments';}else{label=n+' '+(n===1?'comment':'comments');if(nested>0){label+=' ('+nested+' '+(nested===1?'reply':'replies')+')';}}if(h4.textContent!==label){h4.textContent=label;}}}hmBadgeN=n;if(hmBadgeT){clearTimeout(hmBadgeT);}hmBadgeT=setTimeout(paintBadge,500);var sh=document.getElementById('ctampilkan');if(sh){var tt=n>0?'Show comments ('+n+')':'Show comments';if(sh.getAttribute('aria-label')!==tt){sh.setAttribute('aria-label',tt);}}}function bindCount(){var holder=document.getElementById('comment-holder');var root=document.getElementById('comments');if(!holder||!root){return false;}if(window.MutationObserver){new MutationObserver(function(){paintCount();}).observe(holder,{childList:true,subtree:true});}paintCount();return true;}if(!bindCount()){document.addEventListener('DOMContentLoaded',function(){bindCount();});}})();
//

 //
/*BLGCHI001-C171: threaded reply fallback. Google no longer serves the threaded-comments library (data:post.commentSrc renders src=empty on this and independent blogs, goog.comments.render missing, queue stuck), so Reply/Replies are dead platform-wide for v1 threads. This re-implements Reply on the rendered list: move the editor into the per-comment box with parentID, toggle back on repeat click; thread toggles flip their list. Stands down the moment the real library exists (click-time guard). Load more past 50 needs the full renderer and stays a documented limit. No < or && below keeps the inline script XML-clean.*/
(function(){function lib(){var g=window.goog;if(!g){return null;}var c=g.comments;if(!c){return null;}return c.render||null;}var replyParent=null;var origH=null;function ed(){return document.getElementById('comment-editor');}function topBox(){return document.getElementById('top-ce');}function setSrc(elm,id){var src=elm.getAttribute('src')||'';var parts=src.split('#');var base=parts[0].replace(/&parentID=[0-9]+/,'');if(id){base=base+'&parentID='+id;}var out=base;if(parts.length>1){out=base+'#'+parts.slice(1).join('#');}if(elm.getAttribute('src')!==out){elm.setAttribute('src',out);}}function toTop(elm){var top=topBox();if(top){top.appendChild(elm);}if(origH!==null){elm.setAttribute('height',origH);}setSrc(elm,null);replyParent=null;}function onDoc(e){if(lib()){return;}var t=e.target||null;if(!t||!t.closest){return;}var tg=t.closest('#comments .thread-toggle a');if(tg){var th=tg.closest('.comment-thread');var ol=th?th.querySelector('ol.thread-chrome'):null;if(ol){e.preventDefault();if(ol.classList.contains('hidden')){ol.classList.remove('hidden');}else{ol.classList.add('hidden');}}return;}var a=t.closest('#comment-holder a.comment-reply');if(!a){return;}e.preventDefault();var id=a.getAttribute('data-comment-id')||null;var elm=ed();if(!elm){return;}if(origH===null){origH=elm.getAttribute('height')||'89px';}if(id===null||id===replyParent){toTop(elm);return;}var box=document.getElementById(id+'-ce')||document.getElementById('c'+id+'-ce');var dest=box||topBox();if(!dest){return;}dest.appendChild(elm);elm.setAttribute('height','250px');elm.style.display='block';setSrc(elm,id);replyParent=id;}function masks(){var host=document.getElementById('comments');if(!host){return;}var boxes=host.querySelectorAll('#top-ce,.comment-replybox-single');boxes.forEach(function(b){if(!b.querySelector(':scope>.hm-ed-mask')){var s=document.createElement('span');s.className='hm-ed-mask';s.setAttribute('aria-hidden','true');b.appendChild(s);}});}function bind(){var root=document.getElementById('comments');if(!root){return false;}root.addEventListener('click',onDoc);masks();return true;}if(!bind()){document.addEventListener('DOMContentLoaded',function(){bind();});}})();
//

/*BLGCHI001-C219: comment embed parser -- detects YouTube and image URLs in
  Blogger comment text and replaces them with embedded iframes/images. Runs
  after comments load, sanitizes URLs to prevent XSS, responsive embeds.*/
(function(){
  function parseYouTube(url){
    var m=url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
    return m?m[1]:null;
  }
  function isImageUrl(url){
    return /\.(jpg|jpeg|png|gif|webp)(\?.*)?$/i.test(url);
  }
  function sanitizeUrl(url){
    try{
      var u=new URL(url);
      if(u.protocol!=='http:'&&u.protocol!=='https:')return null;
      return u.href;
    }catch(e){return null;}
  }
  function escapeHtml(text){
    var div=document.createElement('div');
    div.textContent=text;
    return div.innerHTML;
  }
  function processComment(el){
    var html=el.innerHTML;
    var urlRegex=/(https?:\/\/[^\s<>"']+)/gi;
    var matches=html.match(urlRegex);
    if(!matches)return;
    matches.forEach(function(url){
      var sanitized=sanitizeUrl(url);
      if(!sanitized)return;
      var ytId=parseYouTube(sanitized);
      if(ytId){
        var embed='<div class="hm-cmt-embed hm-cmt-yt"><iframe width="560" height="315" src="https://www.youtube.com/embed/'+ytId+'" frameborder="0" allowfullscreen loading="lazy"></iframe></div>';
        html=html.replace(url,embed);
      }else if(isImageUrl(sanitized)){
        var img='<div class="hm-cmt-embed hm-cmt-img"><img src="'+escapeHtml(sanitized)+'" alt="User image" loading="lazy"/></div>';
        html=html.replace(url,img);
      }
    });
    el.innerHTML=html;
  }
  function hmRunCommentEmbeds(){
    var comments=document.querySelectorAll('.comment-body,.comment-content,.comments .comment');
    for(var i=0;i<comments.length;i++){
      processComment(comments[i]);
    }
  }
  if(document.readyState==='complete')hmRunCommentEmbeds();
  else window.addEventListener('load',hmRunCommentEmbeds);
  setTimeout(hmRunCommentEmbeds,2000);
})();

