/*BLGCHI001-C101 (B8 stage 3): vanilla port of the jQuery 'lighter'
  lightbox. Contract kept: clicking an image inside an .entry-content
  link opens the same overlay (kept DOM classes: .lighter.fade >
  .lighter-container > .lighter-content/.lighter-close/.lighter-prev/
  .lighter-next + .lighter-overlay) so every kept CSS rule still styles
  it; the image scales to fit the viewport minus the plugin's 40px
  padding; data-width/data-height attributes pre-size the box (the
  plugin's 960x540 default otherwise; natural size takes over on load);
  Esc, the close button and an overlay click dismiss it; a window
  resize refits. Measured: the plugin's prev/next were display:none
  no-ops for a single-image box, so the port renders no arrow logic;
  the arrows keep their parity markup for CSS continuity only. The
  plugin's default (non-image href -> ajax content) had no live
  surface: entry-content image links are the only hookups.*/
(function(){
  var PADDING=40,box=null,curW=960,curH=540;
  function fit(w,h){
    curW=w;curH=h;
    var c=box.querySelector('.lighter-container');
    if(w&&h){
      var sc=Math.max(h/(window.innerHeight-PADDING),w/(window.innerWidth-PADDING));
      if(sc>1){h=Math.round(h/sc);w=Math.round(w/sc);}
    }
    c.style.height=h+'px';c.style.width=w+'px';c.style.margin='-'+(h/2)+'px -'+(w/2)+'px';
  }
  function onKey(e){if(e.which===27)close();}
  function onResize(){fit(curW,curH);}
  function close(){
    if(!box)return;
    var b=box;box=null;
    document.removeEventListener('keyup',onKey);
    window.removeEventListener('resize',onResize);
    b.classList.add('fade');
    setTimeout(function(){if(b.parentNode)b.parentNode.removeChild(b);},250);
  }
  function open(a){
    if(box)return;
    box=document.createElement('div');box.className='lighter fade';
    box.innerHTML="<div class='lighter-container'><span class='lighter-content'/><a class='lighter-close'>&#215;</a><a class='lighter-prev'>&#8249;</a><a class='lighter-next'>&#8250;</a></div><div class='lighter-overlay'/>";
    var span=box.querySelector('.lighter-content');
    var dw=parseInt(a.getAttribute('data-width'),10),dh=parseInt(a.getAttribute('data-height'),10);
    fit(dw>0&&dh>0?dw:960,dh>0&&dh>0?dh:540);
    var img=document.createElement('img');
    img.onload=function(){fit(img.naturalWidth||curW,img.naturalHeight||curH);};
    img.src=a.getAttribute('href')||'';
    span.appendChild(img);
    document.body.appendChild(box);
    box.querySelector('.lighter-close').addEventListener('click',function(e){e.preventDefault();e.stopPropagation();close();});
    box.querySelector('.lighter-overlay').addEventListener('click',function(e){e.preventDefault();close();});
    document.addEventListener('keyup',onKey);
    window.addEventListener('resize',onResize);
    requestAnimationFrame(function(){requestAnimationFrame(function(){if(box)box.classList.remove('fade');});});
  }
  document.addEventListener('click',function(e){
    if(e.target&&e.target.tagName==='IMG'&&!box){
      var p=e.target.closest('a');
      if(p&&p.closest('.entry-content')){e.preventDefault();e.stopPropagation();open(p);}
    }
  },false);
})();
