/*BLGCHI001-C143: vanilla port of the reference stories-overlay toggle -- the
  homepage Highlight tile (#popular-overlay) opens the PopularPosts1
  fullscreen modal (div.overlay.overlay-mbl). C101 removed the only wiring
  (the legacy helper libs + open/close IIFE) with no replacement, leaving
  the tile click-dead on the live blog while the reference demo still opens
  the modal; this restores the contract dependency-free (hmReady + classList,
  visibility-transition cleanup as the CSS owns it). Null-guarded: the
  trigger and modal ship on the homepage only.*/
hmReady(function(){
  var trigger=document.getElementById('popular-overlay');
  var overlay=document.querySelector('.overlay-mbl');
  var closeBtn=overlay?overlay.querySelector('.overlay-close'):null;
  if(!trigger||!overlay||!closeBtn)return;
  var trans=(('transition' in document.body.style)||('webkitTransition' in document.body.style))?'transitionend':null;
  function open(){if(overlay.classList.contains('close'))overlay.classList.remove('close');overlay.classList.add('open');}
  function close(){
    if(!overlay.classList.contains('open'))return;
    overlay.classList.remove('open');overlay.classList.add('close');
    function done(ev){
      if(ev&&ev.propertyName&&ev.propertyName!=='visibility')return;
      if(trans)overlay.removeEventListener(trans,done);
      overlay.classList.remove('close');
    }
    if(trans){overlay.addEventListener(trans,done);}
    else{done();}
  }
  function toggle(){if(overlay.classList.contains('open'))close();else open();}
  trigger.addEventListener('click',toggle);
  closeBtn.addEventListener('click',toggle);
});
