/*BLGCHI001-C153: hmStories v2 -- peek-track carousel for the Highlight modal,
  replacing the C144 swap-in-place engine inside the same contract. The slider
  becomes a viewport around a JS-built .hm-st-track that lays every story on
  one line: the active card is centered and full, the previously shown story
  peeks on the left, and the upcoming story peeks on the right (server-rendered
  thumbnails are already in the DOM, so the neighbor preview appears with no
  extra fetch -- the next highlight is effectively preloaded). Motion: a
  320ms eased track slide with a dim + scale settle on the neighbors. Auto
  advance: every 7 seconds (AUTO=7000) the next story loads, and the
  hm-st-timer bar along the active card's foot is the visible countdown for
  that trigger. Full loop: the 7s timeout (or a right/next step) on the last
  story fires rewindTo(0) -- a 1.05s rollback pass that slides the whole
  track back across every shown highlight to story 01; a left/prev step on
  story 01 rolls back to the last story the same way. The countdown holds
  while the modal is closed, the tab is hidden, the pointer rests on the
  stage, a swipe is in flight, or the rollback is running; manual navigation
  rearms a fresh 7s. Everything from C144 survives: the zero-slide guard,
  arrows + clickable dots + the dynamic NN/MM counter (hm-st-count), the
  polite live region (hm-st-live), ESC/arrow keyboard, the guarded 40px
  swipe, scroll lock with scrollbar compensation, and focus open/close
  management, all on top of the untouched C143 toggle (C143's listeners run
  first, these second).*/
function hmStories(root){
  var slider=root.querySelector('#PopularPosts1 .slider');
  if(!slider)return;
  var slides=slider.querySelectorAll('li.popular_content');
  if(slides.length===0)return;
  var N=slides.length,cur=0,i,j;
  slider.classList.add('hm-stories');
  var track=document.createElement('div');track.className='hm-st-track';
  for(i=0;i<N;i++)track.appendChild(slides[i]);
  slider.insertBefore(track,slider.firstChild);
  var timers=[];
  for(i=0;i<N;i++){(function(k){var bar=document.createElement('div');bar.className='hm-st-timer';var fill=document.createElement('div');fill.className='hm-st-timer-fill';bar.appendChild(fill);slides[k].appendChild(bar);timers.push(fill);})(i);}
  var prevBtn=document.createElement('button');prevBtn.type='button';prevBtn.className='slick-prev';prevBtn.setAttribute('aria-label','Previous story');
  slider.insertBefore(prevBtn,track);
  var nextBtn=document.createElement('button');nextBtn.type='button';nextBtn.className='slick-next';nextBtn.setAttribute('aria-label','Next story');
  slider.appendChild(nextBtn);
  var dotsBox=document.createElement('div');dotsBox.className='slick-dots';var dotsUl=document.createElement('ul');dotsBox.appendChild(dotsUl);slider.appendChild(dotsBox);
  var dots=[];
  for(i=0;i<N;i++){(function(k){
    slides[k].setAttribute('aria-roledescription','slide');
    slides[k].setAttribute('aria-label',(k+1)+' of '+N);
    var li=document.createElement('li');var b=document.createElement('button');b.type='button';
    b.setAttribute('aria-label','Go to story '+(k+1)+' of '+N);
    b.addEventListener('click',function(){show(k);});
    li.appendChild(b);dotsUl.appendChild(li);dots.push(li);
  })(i);}
  var count=document.createElement('div');count.className='hm-st-count';count.setAttribute('aria-hidden','true');slider.appendChild(count);
