function tagload(item) {
    /*BLGCHI001-C132: reserve the row before the fetch (measured 51px of
      staggered title-jerk per item) -- a 44px shimmer in the real wrap swaps
      height-identically for the links; empties and failures remove it.*/
    let p = document.createElement('div');
    p.className = 'popular-tag hm-tag-pending';
    p.setAttribute('aria-hidden', 'true');
    p.innerHTML = '<span class="hm-sk hm-sk-tagbar"></span>';
    var ti0 = item.querySelector('.item-title');
    if (ti0 && ti0.parentNode) ti0.parentNode.insertBefore(p, ti0);
    fetch('/feeds/posts/summary/' + item.dataset.postId + '?alt=json')
        .then(response => response.ok ? response.json() : null)
        .then(json => {
            if (json && json.entry && json.entry.category) {
                let out = [];
                json.entry.category.forEach(category => {
                    out.push('<a href="/search/label/' + encodeURIComponent(category.term) + '?&amp;max-results=20" rel="tag">' + category.term + '</a>');
                });
    /*BLGCHI001-C29 (B8 stage 1): insert the tag row with plain DOM (was $(item).find('.item-title').before(p)).*/
                if (out.length) {
                    p.classList.add('hm-enter');
                    p.classList.remove('hm-tag-pending');
                    p.removeAttribute('aria-hidden');
                    p.innerHTML = out.join('');
                } else if (p.parentNode) { p.parentNode.removeChild(p); }
            } else if (p.parentNode) { p.parentNode.removeChild(p); }
        })
        .catch(() => { if (p.parentNode) { p.parentNode.removeChild(p); } });
}
