render(entries,q);
};
sc.onerror=function(){if(my!==seq)return;try{delete window[cb];}catch(x){}if(sc.parentNode)sc.parentNode.removeChild(sc);setStatus('Feed unreachable -- press Enter for full search.');if(all)all.href=searchURL(q);};
sc.src='/feeds/posts/default?q='+encodeURIComponent(q)+'&alt=json-in-script&max-results=6&callback='+cb;
document.head.appendChild(sc);
}
if(input){input.addEventListener('input',function(){
var q=input.value.replace(/^\s+|\s+$/g,'');
if(all)all.href=searchURL(q||'');
if(timer){clearTimeout(timer);timer=null;}
if(q.length<2){seq++;clear();setStatus('Type 2+ characters for live results.');return;}
setStatus('Searching…');
timer=setTimeout(function go(){seq++;fetchQ(q,seq);},300);
});
input.addEventListener('keydown',function(ev){
if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){
if(!rows.length)return;ev.preventDefault();
if(ev.key==='ArrowDown'){active=(active+1)%rows.length;}else{active=(active-1+rows.length)%rows.length;}
paintActive();
var a=rows[active].querySelector('a');if(a&&a.scrollIntoView)a.scrollIntoView({block:'nearest'});
}else if(ev.key==='Escape'){ev.preventDefault();shut();}
});
if(form){form.addEventListener('submit',function(ev){
if(active>=0&&rows[active])return;
ev.preventDefault();
var q=input.value.replace(/^\s+|\s+$/g,'');
window.location.href=searchURL(q);
});}
}
toggle.addEventListener('click',function(ev){ev.preventDefault();if(panel.hasAttribute('hidden')){open();}else{shut();}});
if(close){close.addEventListener('click',function(){shut();});}
document.addEventListener('keydown',function(ev){if(ev.key==='Escape'&&!panel.hasAttribute('hidden'))shut();});
})();
