/*BLGCHI001-C314 (back-to-top, llianmeva BLG-C562 port): the control appears only after the reader has actually scrolled. Ported method, not markup: 30% of the real scroll range (document height minus viewport), passive scroll/resize listeners with requestAnimationFrame, hidden again at the top; the link leaves the tab order while hidden (visibility removes it). Smooth scroll comes from the theme's html{scroll-behavior:smooth}, the same declarative contract as llianmeva's uk-scroll. C316: init waits for DOMContentLoaded -- the anchor ships at end-of-body AFTER this script, so a direct query reads null and the control never binds (proven live: hidden at 55% scroll). Single IIFE so no scope shadows. */
(function () {
  function init() {
  var toTop = document.querySelector('.icon-to-top');
  if (!toTop) return;
  var SHOW_AT = 0.3;
  var ticking = false;
  function update() {
    var doc = document.documentElement;
    var max = doc.scrollHeight - doc.clientHeight;
    var y = window.pageYOffset || doc.scrollTop || 0;
    toTop.classList.toggle('is-visible', max > 0 && y >= max * SHOW_AT);
  }
  function schedule() {
    if (ticking) return;
    ticking = true;
    var run = function () { ticking = false; update(); };
    if (window.requestAnimationFrame) window.requestAnimationFrame(run);
    else setTimeout(run, 16);
  }
  window.addEventListener('scroll', schedule, { passive: true });
  window.addEventListener('resize', schedule, { passive: true });
  update();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
//

//
// C105 (adopted from blogger-llianmeva-template BLG-C519 + BLG-C520): the
// activated footer line ships as a Layout-editable default whose live parts
// are marker spans -- `.policy-title` (the blog title, read from the
// og:site_name meta rather than document.title, so a POST page does not put
// its own title in the credit) and `.policy-year` (the year). It fills only
// the parts still present and empty, so an owner who edits the widget keeps
// full control, and runs after the guard's fingerprint is taken
// (DOMContentLoaded order), so a moving title or year is never a footer
// change; the observer re-fills after a licensed verdict restores the line.
// The free edition never sees these spans: the guard replaces the whole
// line with its own credit first (see ensureFreeCredit). Root is the
// section itself, so the fill also covers the C104 fallback host.
(function () {
  function fill(root) {
    var t = root.querySelector('.policy-title');
    if (t && !t.textContent) { var m = document.querySelector('meta[property="og:site_name"]'); t.textContent = (m && m.content) ? m.content : document.title; }
    var years = root.querySelectorAll('.policy-year');
    var now = String(new Date().getFullYear());
    for (var i = 0; i < years.length; i++) { if (years[i].textContent !== now) { years[i].textContent = now; } }
  }
  function init() {
    var root = document.querySelector('.copyright-ft');
    if (!root) { return; }
    fill(root);
    if (window.MutationObserver) {
      new MutationObserver(function () { fill(root); }).observe(root, { childList: true, subtree: true, characterData: true });
    } else {
      window.addEventListener('load', function () { fill(root); });
    }
  }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); }
  else { init(); }
})();
//

/*BLGCHI001-C220: shortcut keys -- global keydown listener for common actions.
  Disabled when focus is in form inputs to avoid conflicts. Maps: / = search,
  h = home, d = dark mode, t = scroll top, ? = help modal.*/
(function(){
  var helpModal=document.getElementById('hm-shortcut-help');
  function isInInput(e){
    var tag=e.target.tagName.toLowerCase();
    return tag==='input'||tag==='textarea'||tag==='select'||e.target.isContentEditable;
  }
  function focusSearch(){
    var input=document.getElementById('hm-search-input');
    if(input){input.focus();event.preventDefault();}
  }
  function goHome(){
    window.location.href='/';
  }
  function toggleDark(){
    var btn=document.querySelector('.hm-dark-toggle');
    if(btn)btn.click();
  }
  function scrollTop(){
    window.scrollTo({top:0,behavior:'smooth'});
  }
  function showHelp(){
    if(helpModal){
      helpModal.style.display='flex';
      helpModal.setAttribute('aria-hidden','false');
    }
  }
  function hideHelp(){
    if(helpModal){
      helpModal.style.display='none';
      helpModal.setAttribute('aria-hidden','true');
    }
  }
  document.addEventListener('keydown',function(e){
    if(isInInput(e))return;
    if(e.key==='/'){focusSearch();e.preventDefault();}
    else if(e.key==='h'&&!e.ctrlKey&&!e.metaKey){goHome();e.preventDefault();}
    else if(e.key==='d'&&!e.ctrlKey&&!e.metaKey){toggleDark();e.preventDefault();}
    else if(e.key==='t'&&!e.ctrlKey&&!e.metaKey){scrollTop();e.preventDefault();}
    else if(e.key==='?'||e.key==='/'){showHelp();e.preventDefault();}
    else if(e.key==='Escape'){hideHelp();}
  });
  if(helpModal){
    helpModal.addEventListener('click',function(e){
      if(e.target===helpModal)hideHelp();
    });
  }
})();
